#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
XML-RDF Convertor  Version 1.0


Subcommands:
  - schema   : XSD -> OWL (Turtle) vocabulary/TBox
  - instance : XML(instance) -> RDF (Turtle) ABox, driven by XSD + rules

This file embeds the schema and instance converters so it can be distributed as
a single Python program file.
"""

from __future__ import annotations

import argparse
import sys
import types

PROGRAM_NAME = "XML-RDF Convertor"
PROGRAM_VERSION = "1.0"
__version__ = PROGRAM_VERSION

_SCHEMA_SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\n"""\nXML-RDF Convertor (Version 1.0)\n\nXSD -> OWL (Turtle) converter (ElementTree-based) with:\n  - JSON and TSV rule file support\n  - defaults included template output (init rules)\n  - effective config display (defaults included)\n  - validation warnings when rules are missing / insufficient\n  - measurement-as-object default modelling with per-property overrides\n\nProgram: XML-RDF Convertor\nVersion: 1.0\n\nRule Spec: xml-rdf-convertor-schema-1.0\n\nKey user requirements implemented:\n  1) CLI options are minimal; most behavior is driven by a rule file.\n  2) At runtime, print how conversion will be performed (effective config incl. defaults).\n  3) If rules are insufficient (e.g., base_ns missing), continue converting (force mode)\n     but also warn and show *which* rule keys should be added + an example patch.\n  4) Rule file can be JSON or TSV (text). TSV supports dotted keys, list append `[]`,\n     dict entry `[key]`, and auto-typing of values.\n  5) Program can output a default rules file that includes all defaults (JSON/TSV),\n     and can dump the effective config (defaults + overrides).\n\nDependencies:\n  - rdflib (pip install rdflib)\nParser:\n  - xml.etree.ElementTree (stdlib); uses iterparse and elem.clear()\n\nTypical usage:\n  python xml_rdf_convertor_schema.py ome.xsd --rules ome_rules.tsv -o ome.owl.ttl\n\nTSV format:\n  - UTF-8 recommended (UTF-8 with BOM is OK)\n  - tab-separated columns: key <TAB> value <TAB> (optional comment)\n  - comments: lines starting with # are ignored\n  - arrays: key[] value  (append)\n  - dicts : key[subkey] value\n  - value typing: true/false, int, float, JSON array/object, otherwise string\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport copy\nimport json\nimport re\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Optional, Set, Tuple\n\nimport urllib.parse\nimport xml.etree.ElementTree as ET\n\nfrom rdflib import Graph, Namespace, URIRef, Literal\nfrom rdflib.namespace import RDF, RDFS, OWL, XSD\n\n\n# ----------------------------\n# XML Schema namespace\n# ----------------------------\nXS_NS = "http://www.w3.org/2001/XMLSchema"\nXS = "{%s}" % XS_NS\n\nSPEC_ID = "xml-rdf-convertor-schema-1.0"\n\nPROGRAM_NAME = "XML-RDF Convertor"\nPROGRAM_VERSION = "1.0"\n__version__ = PROGRAM_VERSION\n\n# External property we may declare (optional)\nQUDT_UNIT = URIRef("http://qudt.org/schema/qudt#unit")\n\n# ----------------------------\n# Defaults\n# ----------------------------\n\nDEFAULT_RULES: Dict[str, Any] = {\n    "version": 1,\n    "project": {\n        # REQUIRED for stable URIs; if missing, we warn and fall back to a placeholder\n        "base_ns": "",\n        # Optional: identifier printed in logs\n        "name": ""\n    },\n    "input": {\n        # If input is a single file: whether to follow local include/import schemaLocation\n        "follow_includes": False,\n    },\n    "naming": {\n        "name_style": "raw",  # raw|quote|slug\n        "lower_first_properties": True,\n        # False => global property names; True => contextual: <Domain>/<prop>\n        "contextual_properties": False,\n    },\n    "owl": {\n        "skip_ref_classes": True,\n        "skip_group_classes": True,\n        "skip_id_attributes": True,\n        "enum_as_class": True,\n        # For measurement-like object properties, how to emit range:\n        # "omit" | "thing" | "value_class"\n        "measurement_range_mode": "omit",\n    },\n    "measurement": {\n        # Default modelling for numeric values:\n        # "object" => use ObjectProperty (value object; unit can be attached to that node)\n        # "datatype" => use DatatypeProperty (literal)\n        "numeric_default": "object",\n\n        # If numeric_default == "object", these are exceptions => force literal\n        "unitless_literal_properties": [],\n        "unitless_literal_property_patterns": [],\n\n        # Suffix used to detect XSD unit companion fields (e.g., PhysicalSizeXUnit)\n        "unit_suffix": "Unit",\n\n        # If true, when numeric_default == "object", skip generating explicit *Unit properties,\n        # assuming unit is embedded in the value object (e.g., qudt:unit)\n        "skip_unit_properties": True,\n\n        # If measurement_range_mode == "value_class", this class local name is used as range\n        "value_class_local": "QuantityValue",\n    },\n    "external": {\n        # Optional helper property declarations (schema-level, not required for OWL validity)\n        "emit_rdf_value": True,     # rdf:value a owl:DatatypeProperty\n        "emit_qudt_unit": True,     # qudt:unit a owl:ObjectProperty\n    },\n    "validation": {\n        # "force": convert even if missing rules, minimal warnings\n        # "warn" : convert + warn about missing/insufficient rules (recommended)\n        # "strict": abort on critical missing rules (e.g., base_ns)\n        "mode": "warn",\n\n        # If true, print actionable patches when issues exist\n        "print_patches": True,\n\n        # Optional: write TODO patch file (format by extension .json/.tsv)\n        "todo_patch_path": "",\n    },\n    "logging": {\n        # "summary" | "full" | "none"\n        "print_effective_config": "summary",\n        "quiet": False,\n    },\n    "verify": {\n        "enabled": False,\n        "reference_ttl": "",\n        # Optional outputs\n        "report_json": "",\n        "report_csv": "",\n    }\n}\n\nPLACEHOLDER_BASE_NS = "http://example.org/ontology/"\n\n\n# ----------------------------\n# Helpers: name encoding\n# ----------------------------\n\ndef _slug(s: str) -> str:\n    import unicodedata\n    s = unicodedata.normalize("NFKC", s).strip().lower()\n    s = re.sub(r"\\s+", "-", s)\n    s = re.sub(r"[^\\w\\-]", "", s)\n    return s or "unnamed"\n\ndef encode_name(name: str, style: str) -> str:\n    name = (name or "").strip()\n    if style == "quote":\n        return urllib.parse.quote(name, safe="")\n    if style == "slug":\n        return _slug(name)\n    return name\n\ndef split_qname(qname: str) -> Tuple[str, str]:\n    if qname and ":" in qname:\n        p, l = qname.split(":", 1)\n        return p, l\n    return "", qname or ""\n\ndef lower_first(name: str) -> str:\n    if not name:\n        return name\n    if len(name) == 1:\n        return name.lower()\n    return name[0].lower() + name[1:]\n\ndef is_ref_name(name: str) -> bool:\n    return name.endswith("Ref")\n\ndef is_group_name(name: str) -> bool:\n    return name.endswith("Group")\n\ndef strip_ref(name: str) -> str:\n    return name[:-3] if is_ref_name(name) else name\n\ndef get_doc(elem: ET.Element) -> Optional[str]:\n    doc = elem.find(f"{XS}annotation/{XS}documentation")\n    if doc is None:\n        return None\n    txt = "".join(doc.itertext()).strip()\n    return txt or None\n\n\n# ----------------------------\n# TSV rule file parsing/writing\n# ----------------------------\n\ndef parse_scalar(value: str) -> Any:\n    """Parse TSV value into bool/int/float/json/list/dict/string."""\n    v = value.strip()\n    if v == "":\n        return ""\n    low = v.lower()\n    if low in ("true", "false"):\n        return low == "true"\n    # int\n    if re.fullmatch(r"[+-]?\\d+", v):\n        try:\n            return int(v)\n        except ValueError:\n            pass\n    # float\n    if re.fullmatch(r"[+-]?\\d+\\.\\d+", v):\n        try:\n            return float(v)\n        except ValueError:\n            pass\n    # json list/dict\n    if (v.startswith("[") and v.endswith("]")) or (v.startswith("{") and v.endswith("}")):\n        try:\n            return json.loads(v)\n        except json.JSONDecodeError:\n            return v\n    return v\n\n_KEY_ARRAY = re.compile(r"^(?P<path>.+)\\[\\]$")\n_KEY_MAP = re.compile(r"^(?P<path>.+)\\[(?P<subkey>.+)\\]$")\n\ndef set_by_dotted_path(obj: Dict[str, Any], dotted: str, value: Any) -> None:\n    """Set obj[a][b][c] = value for dotted path \'a.b.c\'."""\n    parts = dotted.split(".")\n    cur: Dict[str, Any] = obj\n    for p in parts[:-1]:\n        if p not in cur or not isinstance(cur[p], dict):\n            cur[p] = {}\n        cur = cur[p]\n    cur[parts[-1]] = value\n\ndef get_by_dotted_path(obj: Dict[str, Any], dotted: str) -> Any:\n    cur: Any = obj\n    for p in dotted.split("."):\n        if not isinstance(cur, dict) or p not in cur:\n            return None\n        cur = cur[p]\n    return cur\n\ndef load_rules_tsv(path: Path) -> Dict[str, Any]:\n    """\n    TSV rules:\n      key<TAB>value<TAB>(optional comment)\n    Supports:\n      a.b.c      value\n      a.b.list[] item\n      a.b.map[k] value\n    """\n    rules: Dict[str, Any] = {}\n    text = path.read_text(encoding="utf-8-sig")\n    for lineno, raw in enumerate(text.splitlines(), start=1):\n        line = raw.strip("\\n\\r")\n        if not line.strip():\n            continue\n        if line.lstrip().startswith("#"):\n            continue\n        parts = line.split("\\t")\n        if len(parts) < 2:\n            continue\n        key = parts[0].strip()\n        val_raw = parts[1]\n        val = parse_scalar(val_raw)\n\n        if key == "":\n            continue\n\n        m_arr = _KEY_ARRAY.match(key)\n        if m_arr:\n            base = m_arr.group("path")\n            existing = get_by_dotted_path(rules, base)\n            if existing is None:\n                set_by_dotted_path(rules, base, [])\n                existing = get_by_dotted_path(rules, base)\n            if not isinstance(existing, list):\n                # if user accidentally set scalar, override to list\n                set_by_dotted_path(rules, base, [])\n                existing = get_by_dotted_path(rules, base)\n            existing.append(val)\n            continue\n\n        m_map = _KEY_MAP.match(key)\n        if m_map:\n            base = m_map.group("path")\n            subkey = m_map.group("subkey")\n            existing = get_by_dotted_path(rules, base)\n            if existing is None:\n                set_by_dotted_path(rules, base, {})\n                existing = get_by_dotted_path(rules, base)\n            if not isinstance(existing, dict):\n                set_by_dotted_path(rules, base, {})\n                existing = get_by_dotted_path(rules, base)\n            existing[subkey] = val\n            continue\n\n        # plain dotted path\n        set_by_dotted_path(rules, key, val)\n\n    return rules\n\ndef flatten_for_tsv(obj: Any, prefix: str = "") -> List[Tuple[str, Any]]:\n    """\n    Flatten nested dict for TSV output.\n    For dict leafs, expands into key[subkey] lines.\n    For lists, expands into key[] lines.\n    """\n    out: List[Tuple[str, Any]] = []\n    if isinstance(obj, dict):\n        for k in sorted(obj.keys()):\n            v = obj[k]\n            p = f"{prefix}.{k}" if prefix else k\n            # For dicts, continue recursion. But if this dict is intended as "map" (leaf dict),\n            # we still recurse; output will be [subkey] at leaves if values are scalars.\n            out.extend(flatten_for_tsv(v, p))\n        return out\n\n    if isinstance(obj, list):\n        key = prefix\n        if not obj:\n            out.append((key, []))\n        else:\n            for item in obj:\n                out.append((key + "[]", item))\n        return out\n\n    # scalar\n    out.append((prefix, obj))\n    return out\n\ndef tsv_value_repr(v: Any) -> str:\n    if isinstance(v, bool):\n        return "true" if v else "false"\n    if isinstance(v, (int, float)):\n        return str(v)\n    if isinstance(v, list) or isinstance(v, dict):\n        return json.dumps(v, ensure_ascii=False)\n    return "" if v is None else str(v)\n\ndef write_rules_tsv(path: Path, rules: Dict[str, Any], *, include_header: bool = True) -> None:\n    lines: List[str] = []\n    if include_header:\n        lines.append("# xsd2owl rules (TSV)")\n        lines.append(f"# spec\\t{SPEC_ID}")\n        lines.append("# format:\\tkey<TAB>value<TAB>(optional comment)")\n        lines.append("# arrays:\\tkey[] value (append)")\n        lines.append("# maps:\\tkey[subkey] value")\n        lines.append("#")\n    # provide a few helpful comments for key settings\n    notes = {\n        "project.base_ns": "REQUIRED: base namespace for generated ontology terms (end with / recommended).",\n        "validation.mode": "force|warn|strict",\n        "measurement.numeric_default": "object|datatype",\n        "owl.measurement_range_mode": "omit|thing|value_class",\n    }\n    flat = flatten_for_tsv(rules)\n    for key, val in flat:\n        comment = notes.get(key, "")\n        lines.append(f"{key}\\t{tsv_value_repr(val)}" + (f"\\t# {comment}" if comment else ""))\n    path.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n\ndef load_rules_file(path: Optional[str]) -> Tuple[Dict[str, Any], str]:\n    """\n    Returns (rules_override, format) where format is \'json\'|\'tsv\'|\'none\'.\n    """\n    if not path:\n        return {}, "none"\n    p = Path(path)\n    if not p.exists():\n        raise FileNotFoundError(f"Rules file not found: {path}")\n    ext = p.suffix.lower()\n    if ext == ".json":\n        return json.loads(p.read_text(encoding="utf-8-sig")), "json"\n    # treat everything else as TSV-ish (tsv/txt)\n    return load_rules_tsv(p), "tsv"\n\ndef deep_update(dst: Dict[str, Any], src: Dict[str, Any]) -> None:\n    """Recursive dict update; overwrites non-dict leaves."""\n    for k, v in src.items():\n        if isinstance(v, dict) and isinstance(dst.get(k), dict):\n            deep_update(dst[k], v)  # type: ignore[index]\n        else:\n            dst[k] = copy.deepcopy(v)\n\ndef compute_effective_rules(defaults: Dict[str, Any], overrides: Dict[str, Any]) -> Dict[str, Any]:\n    eff = copy.deepcopy(defaults)\n    deep_update(eff, overrides)\n    return eff\n\n\n# ----------------------------\n# Validation (missing/insufficient rules)\n# ----------------------------\n\n@dataclass\nclass RuleIssue:\n    code: str\n    level: str  # "WARN" | "ERROR"\n    message: str\n    missing_keys: List[str] = field(default_factory=list)\n    suggested_patch: Dict[str, Any] = field(default_factory=dict)\n    details: Dict[str, Any] = field(default_factory=dict)\n\ndef format_patch_json(patch: Dict[str, Any]) -> str:\n    return json.dumps(patch, ensure_ascii=False, indent=2)\n\ndef format_patch_tsv(patch: Dict[str, Any]) -> str:\n    flat = flatten_for_tsv(patch)\n    # Keep header off for patch snippet\n    lines = []\n    for k, v in flat:\n        lines.append(f"{k}\\t{tsv_value_repr(v)}")\n    return "\\n".join(lines)\n\ndef add_issue(issues: List[RuleIssue], issue: RuleIssue) -> None:\n    issues.append(issue)\n\ndef validate_rules(effective: Dict[str, Any], *, rules_format: str) -> Tuple[Dict[str, Any], List[RuleIssue]]:\n    """\n    Validate and normalize effective rules.\n    Returns (effective_normalized, issues).\n    """\n    eff = copy.deepcopy(effective)\n    issues: List[RuleIssue] = []\n\n    # base_ns: normalize and warn if missing\n    base_ns = (eff.get("project", {}) or {}).get("base_ns", "")\n    if not isinstance(base_ns, str):\n        base_ns = str(base_ns)\n    base_ns = base_ns.strip()\n    if base_ns == "":\n        # [XV-001]\n        add_issue(issues, RuleIssue(\n            code="XV-001",\n            level="ERROR",\n            message="project.base_ns が未指定です。URI生成のため base_ns が必要です。暫定的にプレースホルダで変換を続行します。",\n            missing_keys=["project.base_ns"],\n            suggested_patch={"project": {"base_ns": "http://your.example.org/ontology/"}},\n        ))\n        base_ns = PLACEHOLDER_BASE_NS\n    # ensure trailing slash\n    if not base_ns.endswith("/"):\n        # keep but normalize\n        add_issue(issues, RuleIssue(\n            code="XV-002",\n            level="WARN",\n            message="project.base_ns が \'/\' で終わっていません。正規化のため末尾に \'/\' を付与して使用します。",\n            missing_keys=[],\n            suggested_patch={"project": {"base_ns": base_ns + "/"}},\n            details={"original": base_ns},\n        ))\n        base_ns = base_ns + "/"\n    eff.setdefault("project", {})["base_ns"] = base_ns  # type: ignore[index]\n\n    # validation.mode sanity\n    mode = ((eff.get("validation", {}) or {}).get("mode", "warn") or "warn").lower()\n    if mode not in ("force", "warn", "strict"):\n        add_issue(issues, RuleIssue(\n            code="XV-003",\n            level="WARN",\n            message=f\'validation.mode="{mode}" は未知です。warn として扱います。\',\n            suggested_patch={"validation": {"mode": "warn"}}\n        ))\n        mode = "warn"\n    eff.setdefault("validation", {})["mode"] = mode  # type: ignore[index]\n\n    # measurement defaults sanity\n    numeric_default = ((eff.get("measurement", {}) or {}).get("numeric_default", "object") or "object").lower()\n    if numeric_default not in ("object", "datatype"):\n        add_issue(issues, RuleIssue(\n            code="XV-004",\n            level="WARN",\n            message=f\'measurement.numeric_default="{numeric_default}" は未知です。object として扱います。\',\n            suggested_patch={"measurement": {"numeric_default": "object"}}\n        ))\n        numeric_default = "object"\n    eff.setdefault("measurement", {})["numeric_default"] = numeric_default  # type: ignore[index]\n\n    # logging\n    quiet = bool((eff.get("logging", {}) or {}).get("quiet", False))\n    eff.setdefault("logging", {})["quiet"] = quiet  # type: ignore[index]\n\n    # rule format note (optional)\n    eff.setdefault("runtime", {})["rules_format"] = rules_format  # type: ignore[index]\n\n    return eff, issues\n\ndef print_issues(issues: List[RuleIssue], *, rules_format: str, print_patches: bool = True) -> None:\n    if not issues:\n        return\n    print("\\n=== Rule validation / missing rules ===")\n    for iss in issues:\n        print(f"[{iss.level}][{iss.code}] {iss.message}")\n        if iss.missing_keys:\n            print("  Missing/required keys:")\n            for k in iss.missing_keys:\n                print(f"    - {k}")\n        if print_patches and iss.suggested_patch:\n            print("  Suggested patch:")\n            if rules_format == "tsv":\n                print(format_patch_tsv(iss.suggested_patch))\n            else:\n                print(format_patch_json(iss.suggested_patch))\n        if iss.details:\n            print("  Details:")\n            for k, v in iss.details.items():\n                print(f"    {k}: {v}")\n    print("=== End of rule validation ===\\n")\n\n\n# ----------------------------\n# Effective config display\n# ----------------------------\n\ndef print_effective_config(eff: Dict[str, Any], mode: str) -> None:\n    """\n    Print effective configuration including defaults.\n    mode: "summary"|"full"|"none"\n    """\n    if mode == "none":\n        return\n\n    proj = eff.get("project", {}) or {}\n    base_ns = proj.get("base_ns", "")\n    name = proj.get("name", "")\n\n    print("\\n=== Effective conversion configuration (defaults included) ===")\n    print(f"{PROGRAM_NAME} {PROGRAM_VERSION}")\n    if name:\n        print(f"Project: {name}")\n    print(f"Spec: {SPEC_ID}")\n    print(f"Base namespace: {base_ns}")\n\n    # Summary sections\n    if mode == "summary":\n        for sec in ("input", "naming", "owl", "measurement", "external", "validation", "verify", "logging"):\n            if sec in eff:\n                print(f"\\n[{sec}]")\n                # print each key in section on one line\n                section = eff.get(sec, {}) or {}\n                if isinstance(section, dict):\n                    for k in sorted(section.keys()):\n                        v = section[k]\n                        # shorten long lists\n                        if isinstance(v, list):\n                            print(f"  {k}: list(len={len(v)})" + (f" {v[:8]}..." if len(v) > 8 else f" {v}"))\n                        elif isinstance(v, dict):\n                            print(f"  {k}: dict(len={len(v)})")\n                        else:\n                            print(f"  {k}: {v}")\n                else:\n                    print(f"  {section}")\n        print("\\n=== End effective configuration ===\\n")\n        return\n\n    # Full: pretty JSON\n    print(json.dumps(eff, ensure_ascii=False, indent=2))\n    print("\\n=== End effective configuration ===\\n")\n\n\n# ----------------------------\n# XSD discovery (include/import)\n# ----------------------------\n\ndef iter_xsd_files(path: Path) -> Iterable[Path]:\n    if path.is_file():\n        yield path\n    else:\n        for p in sorted(path.rglob("*.xsd")):\n            yield p\n\ndef extract_schema_locations(xsd_file: Path) -> List[str]:\n    locs: List[str] = []\n    for _, elem in ET.iterparse(str(xsd_file), events=("end",)):\n        if elem.tag in (XS + "include", XS + "import"):\n            loc = elem.get("schemaLocation")\n            if loc:\n                locs.append(loc)\n        elem.clear()\n    return locs\n\ndef discover_xsd_set(input_path: Path, follow_includes: bool) -> Tuple[List[Path], List[Tuple[Path, str]]]:\n    unresolved: List[Tuple[Path, str]] = []\n    if input_path.is_dir():\n        files = list(iter_xsd_files(input_path))\n        return files, unresolved\n\n    start = input_path.resolve()\n    if not follow_includes:\n        return [start], unresolved\n\n    seen: Set[Path] = set()\n    queue: List[Path] = [start]\n\n    while queue:\n        f = queue.pop(0).resolve()\n        if f in seen:\n            continue\n        if not f.exists():\n            continue\n        seen.add(f)\n\n        for loc in extract_schema_locations(f):\n            cand = (f.parent / loc).resolve()\n            if cand.exists() and cand.suffix.lower() == ".xsd":\n                if cand not in seen:\n                    queue.append(cand)\n            else:\n                unresolved.append((f, loc))\n\n    return sorted(seen), unresolved\n\n\n# ----------------------------\n# Index structures\n# ----------------------------\n\n@dataclass\nclass NamedSimpleType:\n    name: str\n    base_qname: Optional[str] = None\n    enumerations: List[str] = field(default_factory=list)\n    docs: List[str] = field(default_factory=list)\n\n@dataclass\nclass NamedComplexType:\n    name: str\n    base_qname: Optional[str] = None\n    derivation: Optional[str] = None\n    docs: List[str] = field(default_factory=list)\n\n@dataclass\nclass TopElement:\n    name: str\n    docs: List[str] = field(default_factory=list)\n    type_qname: Optional[str] = None\n\n@dataclass\nclass XsdIndex:\n    top_elements: Dict[str, TopElement] = field(default_factory=dict)\n    named_complex_types: Dict[str, NamedComplexType] = field(default_factory=dict)\n    named_simple_types: Dict[str, NamedSimpleType] = field(default_factory=dict)\n\ndef build_index(files: List[Path]) -> XsdIndex:\n    """\n    Streaming index across file set:\n      - top-level elements (+ their @type if any)\n      - named complexType / named simpleType (base, enums)\n    """\n    idx = XsdIndex()\n\n    for xsd_path in files:\n        tag_stack: List[str] = []\n        ctx_stack: List[dict] = []\n\n        def nearest_type_ctx() -> Optional[dict]:\n            for c in reversed(ctx_stack):\n                if c["kind"] in ("namedComplexType", "namedSimpleType"):\n                    return c\n            return None\n\n        for ev, elem in ET.iterparse(str(xsd_path), events=("start", "end")):\n            if ev == "start":\n                tag_stack.append(elem.tag)\n\n                if elem.tag == XS + "complexType" and elem.get("name"):\n                    name = elem.get("name")\n                    ctx_stack.append({"kind": "namedComplexType", "name": name, "docs": [], "base": None, "derivation": None})\n                    idx.named_complex_types.setdefault(name, NamedComplexType(name=name))\n\n                if elem.tag == XS + "simpleType" and elem.get("name"):\n                    name = elem.get("name")\n                    ctx_stack.append({"kind": "namedSimpleType", "name": name, "docs": [], "base": None, "enums": []})\n                    idx.named_simple_types.setdefault(name, NamedSimpleType(name=name))\n\n                if elem.tag in (XS + "extension", XS + "restriction"):\n                    tctx = nearest_type_ctx()\n                    if tctx and tctx["kind"] == "namedComplexType":\n                        base = elem.get("base")\n                        if base:\n                            tctx["base"] = base\n                            tctx["derivation"] = "extension" if elem.tag.endswith("extension") else "restriction"\n                    elif tctx and tctx["kind"] == "namedSimpleType" and elem.tag.endswith("restriction"):\n                        base = elem.get("base")\n                        if base:\n                            tctx["base"] = base\n\n            else:\n                if elem.tag == XS + "documentation":\n                    doc = "".join(elem.itertext()).strip()\n                    if doc:\n                        tctx = nearest_type_ctx()\n                        if tctx:\n                            tctx["docs"].append(doc)\n\n                if elem.tag == XS + "enumeration":\n                    val = elem.get("value")\n                    if val is not None:\n                        tctx = nearest_type_ctx()\n                        if tctx and tctx["kind"] == "namedSimpleType":\n                            tctx["enums"].append(val)\n\n                if elem.tag == XS + "element":\n                    parent_tag = tag_stack[-2] if len(tag_stack) >= 2 else None\n                    if parent_tag == XS + "schema":\n                        name = elem.get("name")\n                        if name:\n                            idx.top_elements.setdefault(name, TopElement(name=name))\n                            idx.top_elements[name].type_qname = elem.get("type")\n                            d = get_doc(elem)\n                            if d:\n                                idx.top_elements[name].docs.append(d)\n\n                if elem.tag == XS + "complexType" and elem.get("name"):\n                    if ctx_stack and ctx_stack[-1]["kind"] == "namedComplexType" and ctx_stack[-1]["name"] == elem.get("name"):\n                        tctx = ctx_stack.pop()\n                        info = idx.named_complex_types[tctx["name"]]\n                        info.docs.extend(tctx["docs"])\n                        info.base_qname = tctx.get("base")\n                        info.derivation = tctx.get("derivation")\n\n                if elem.tag == XS + "simpleType" and elem.get("name"):\n                    if ctx_stack and ctx_stack[-1]["kind"] == "namedSimpleType" and ctx_stack[-1]["name"] == elem.get("name"):\n                        tctx = ctx_stack.pop()\n                        info = idx.named_simple_types[tctx["name"]]\n                        info.docs.extend(tctx["docs"])\n                        info.base_qname = tctx.get("base")\n                        info.enumerations.extend(tctx.get("enums", []))\n\n                if tag_stack:\n                    tag_stack.pop()\n                elem.clear()\n\n    return idx\n\n\n# ----------------------------\n# Type classification helpers\n# ----------------------------\n\nNUMERIC_XSD_TYPES = {\n    "decimal","float","double",\n    "integer","nonPositiveInteger","negativeInteger","long","int","short","byte",\n    "nonNegativeInteger","unsignedLong","unsignedInt","unsignedShort","unsignedByte","positiveInteger"\n}\n\ndef is_numeric_qname(qname: Optional[str], idx: XsdIndex, _seen: Optional[Set[str]] = None) -> bool:\n    if not qname:\n        return False\n    _seen = _seen or set()\n    if qname in _seen:\n        return False\n    _seen.add(qname)\n\n    pfx, local = split_qname(qname)\n    if pfx in ("xsd", "xs"):\n        return local in NUMERIC_XSD_TYPES\n\n    if local in idx.named_simple_types:\n        base = idx.named_simple_types[local].base_qname\n        return is_numeric_qname(base, idx, _seen)\n    return False\n\ndef resolve_type_kind(qname: Optional[str], idx: XsdIndex, enum_as_class: bool) -> Tuple[str, str, bool]:\n    """\n    Returns (kind, value, is_unknown_type)\n      kind: "datatype"|"class"\n      value: "xsd:string" or local name for named types\n    """\n    if not qname:\n        return ("datatype", "xsd:string", False)\n    pfx, local = split_qname(qname)\n\n    if pfx in ("xsd", "xs"):\n        return ("datatype", f"xsd:{local}", False)\n\n    if local in idx.named_complex_types:\n        return ("class", local, False)\n\n    if local in idx.named_simple_types:\n        st = idx.named_simple_types[local]\n        if enum_as_class and st.enumerations:\n            return ("class", local, False)\n        return ("datatype", local, False)\n\n    # unknown/external\n    return ("class", local, True)\n\n\n# ----------------------------\n# Internal defs for OWL\n# ----------------------------\n\n@dataclass\nclass ClassDef:\n    name: str\n    superclasses: Set[str] = field(default_factory=set)\n    comment: Optional[str] = None\n\n@dataclass\nclass PropDef:\n    name: str\n    kind: str  # "object" | "datatype"\n    domains: Set[str] = field(default_factory=set)\n    ranges: Set[str] = field(default_factory=set)  # class name or "xsd:datatype"\n    comment: Optional[str] = None\n    # extra metadata for validation/hints\n    meta: Dict[str, Any] = field(default_factory=dict)\n\ndef add_prop(props: Dict[str, PropDef], pname: str, kind: str, domain: str, rng: Optional[str], comment: Optional[str], meta: Optional[Dict[str, Any]] = None):\n    if pname not in props:\n        props[pname] = PropDef(name=pname, kind=kind)\n    p = props[pname]\n    if p.kind != kind:\n        # prefer object property if conflict\n        p.kind = "object" if "object" in (p.kind, kind) else p.kind\n    p.domains.add(domain)\n    if rng:\n        p.ranges.add(rng)\n    if comment and not p.comment:\n        p.comment = comment\n    if meta:\n        p.meta.update(meta)\n\n\n# ----------------------------\n# Build OWL defs (pass 2)\n# ----------------------------\n\ndef compile_regex_list(patterns: List[str]) -> List[re.Pattern]:\n    out = []\n    for p in patterns:\n        try:\n            out.append(re.compile(p))\n        except re.error:\n            continue\n    return out\n\ndef build_defs(files: List[Path], idx: XsdIndex, rules: Dict[str, Any]) -> Tuple[Dict[str, ClassDef], Dict[str, PropDef], Dict[str, Any]]:\n    """\n    Extract OWL classes/properties according to rules.\n    Returns (classes, props, extraction_stats).\n    """\n    naming = rules.get("naming", {}) or {}\n    owl_cfg = rules.get("owl", {}) or {}\n    meas = rules.get("measurement", {}) or {}\n\n    lower_first_properties = bool(naming.get("lower_first_properties", True))\n    contextual_properties = bool(naming.get("contextual_properties", False))\n\n    skip_ref_classes = bool(owl_cfg.get("skip_ref_classes", True))\n    skip_group_classes = bool(owl_cfg.get("skip_group_classes", True))\n    skip_id_attributes = bool(owl_cfg.get("skip_id_attributes", True))\n    enum_as_class = bool(owl_cfg.get("enum_as_class", True))\n\n    numeric_default = (meas.get("numeric_default", "object") or "object").lower()\n    unit_suffix = str(meas.get("unit_suffix", "Unit") or "Unit")\n    skip_unit_properties = bool(meas.get("skip_unit_properties", True))\n\n    unitless_list = set(meas.get("unitless_literal_properties", []) or [])\n    unitless_patterns = compile_regex_list(meas.get("unitless_literal_property_patterns", []) or [])\n\n    def is_unitless_literal(pname_final: str, pname_raw: str) -> bool:\n        if pname_final in unitless_list or pname_raw in unitless_list:\n            return True\n        for rx in unitless_patterns:\n            if rx.search(pname_final) or rx.search(pname_raw):\n                return True\n        return False\n\n    classes: Dict[str, ClassDef] = {}\n    props: Dict[str, PropDef] = {}\n\n    stats = {\n        "unknown_types": set(),\n        "numeric_without_unit_pair": set(),\n        "unit_props_unpaired": set(),\n        "unitless_literal_not_found": set(),\n        "numeric_default": numeric_default,\n    }\n\n    def ensure_class(name: str, comment: Optional[str] = None):\n        if not name:\n            return\n        if name not in classes:\n            classes[name] = ClassDef(name=name, comment=comment)\n        else:\n            if comment and not classes[name].comment:\n                classes[name].comment = comment\n\n    # Include all named complexTypes as classes\n    for name, info in idx.named_complex_types.items():\n        ensure_class(name, info.docs[0] if info.docs else None)\n        if info.base_qname:\n            _, base_local = split_qname(info.base_qname)\n            ensure_class(base_local)\n            classes[name].superclasses.add(base_local)\n\n    # Include top-level elements as classes (unless skipped)\n    for name, info in idx.top_elements.items():\n        if skip_group_classes and is_group_name(name):\n            continue\n        if skip_ref_classes and is_ref_name(name):\n            continue\n        ensure_class(name, info.docs[0] if info.docs else None)\n\n        # If element has @type referencing a named complexType, you can model as subclass\n        # (purely structural; optional behavior could be rule-driven later).\n        if info.type_qname:\n            _, local = split_qname(info.type_qname)\n            if local in idx.named_complex_types and local != name:\n                ensure_class(local)\n                classes[name].superclasses.add(local)\n\n    def prop_name_from(raw: str) -> str:\n        return lower_first(raw) if lower_first_properties else raw\n\n    def final_prop_name(domain: str, raw_name: str, *, is_attr: bool = False) -> Tuple[str, str]:\n        pname_raw = prop_name_from(raw_name)\n        pname = pname_raw\n        if contextual_properties:\n            if is_attr:\n                pname = f"{domain}/@{pname_raw}"\n            else:\n                pname = f"{domain}/{pname_raw}"\n        return pname, pname_raw\n\n    # Parse schema-level complexType and element definitions; extract properties\n    for xsd_path in files:\n        tag_stack: List[str] = []\n\n        for ev, elem in ET.iterparse(str(xsd_path), events=("start", "end")):\n            if ev == "start":\n                tag_stack.append(elem.tag)\n                continue\n\n            parent_tag = tag_stack[-2] if len(tag_stack) >= 2 else None\n\n            # Named complexType definition\n            if elem.tag == XS + "complexType" and parent_tag == XS + "schema" and elem.get("name"):\n                domain = elem.get("name")\n                if domain in classes:\n                    _extract_props_from_complex_type(\n                        elem, domain, idx, classes, props,\n                        enum_as_class=enum_as_class,\n                        final_prop_name=final_prop_name,\n                        skip_id_attributes=skip_id_attributes,\n                        numeric_default=numeric_default,\n                        is_unitless_literal=is_unitless_literal,\n                        unit_suffix=unit_suffix,\n                        skip_unit_properties=skip_unit_properties,\n                        stats=stats,\n                    )\n                elem.clear()\n\n            # Top-level element definition (inline complexType)\n            if elem.tag == XS + "element" and parent_tag == XS + "schema" and elem.get("name"):\n                domain = elem.get("name")\n                if domain in classes:\n                    ct = elem.find(f"{XS}complexType")\n                    if ct is not None:\n                        # extension base -> subclass\n                        ext = ct.find(f".//{XS}extension")\n                        if ext is not None and ext.get("base"):\n                            _, base_local = split_qname(ext.get("base"))\n                            ensure_class(base_local)\n                            classes[domain].superclasses.add(base_local)\n\n                        _extract_props_from_complex_type(\n                            ct, domain, idx, classes, props,\n                            enum_as_class=enum_as_class,\n                            final_prop_name=final_prop_name,\n                            skip_id_attributes=skip_id_attributes,\n                            numeric_default=numeric_default,\n                            is_unitless_literal=is_unitless_literal,\n                            unit_suffix=unit_suffix,\n                            skip_unit_properties=skip_unit_properties,\n                            stats=stats,\n                        )\n                elem.clear()\n\n            if tag_stack:\n                tag_stack.pop()\n\n    # Validate unitless_literal_properties existence (best-effort)\n    if unitless_list:\n        all_prop_names = set(props.keys())\n        for pname in unitless_list:\n            if pname not in all_prop_names:\n                stats["unitless_literal_not_found"].add(pname)\n\n    # Convert sets to sorted lists for stats output\n    stats["unknown_types"] = sorted(list(stats["unknown_types"]))\n    stats["numeric_without_unit_pair"] = sorted(list(stats["numeric_without_unit_pair"]))\n    stats["unit_props_unpaired"] = sorted(list(stats["unit_props_unpaired"]))\n    stats["unitless_literal_not_found"] = sorted(list(stats["unitless_literal_not_found"]))\n    return classes, props, stats\n\ndef _extract_props_from_complex_type(ct_elem: ET.Element,\n                                    domain: str,\n                                    idx: XsdIndex,\n                                    classes: Dict[str, ClassDef],\n                                    props: Dict[str, PropDef],\n                                    *,\n                                    enum_as_class: bool,\n                                    final_prop_name,\n                                    skip_id_attributes: bool,\n                                    numeric_default: str,\n                                    is_unitless_literal,\n                                    unit_suffix: str,\n                                    skip_unit_properties: bool,\n                                    stats: Dict[str, Any]):\n    """\n    Extract child elements and attributes from a complexType element and populate props.\n    """\n\n    def ensure_class(name: str):\n        if name and name not in classes:\n            classes[name] = ClassDef(name=name)\n\n    # Walk compositors recursively\n    def walk_groups(node: ET.Element):\n        for ch in list(node):\n            if ch.tag in (XS + "sequence", XS + "choice", XS + "all"):\n                yield from walk_groups(ch)\n            elif ch.tag == XS + "element":\n                yield ch\n\n    # Collect attribute/element names to detect paired unit properties\n    attr_names: Set[str] = set()\n    for at in ct_elem.findall(f".//{XS}attribute"):\n        aname = at.get("name")\n        if aname:\n            attr_names.add(aname)\n\n    elem_names: Set[str] = set()\n    for el in walk_groups(ct_elem):\n        n = el.get("name")\n        if n:\n            elem_names.add(n)\n\n    def has_unit_pair(base_name: str) -> bool:\n        return (base_name + unit_suffix) in attr_names or (base_name + unit_suffix) in elem_names\n\n    def is_unit_name(name: str) -> bool:\n        return name.endswith(unit_suffix)\n\n    # Elements\n    for el in walk_groups(ct_elem):\n        ref = el.get("ref")\n        name = el.get("name")\n\n        if ref:\n            # reference to global element\n            _, ref_local = split_qname(ref)\n            target = strip_ref(ref_local) if is_ref_name(ref_local) else ref_local\n            ensure_class(target)\n            pname, pname_raw = final_prop_name(domain, strip_ref(ref_local) if is_ref_name(ref_local) else ref_local, is_attr=False)\n            add_prop(props, pname, "object", domain, target, get_doc(el))\n            continue\n\n        if not name:\n            continue\n\n        # Skip unit properties when paired and configured\n        if skip_unit_properties and is_unit_name(name) and (name[:-len(unit_suffix)] in attr_names or name[:-len(unit_suffix)] in elem_names):\n            continue\n\n        pname, pname_raw = final_prop_name(domain, name, is_attr=False)\n\n        qtype = el.get("type")\n        if qtype:\n            kind, val, is_unknown = resolve_type_kind(qtype, idx, enum_as_class)\n            if is_unknown:\n                stats["unknown_types"].add(qtype)\n            if kind == "class":\n                ensure_class(val)\n                add_prop(props, pname, "object", domain, val, get_doc(el))\n            else:\n                # datatype-like; apply measurement numeric_default\n                if is_numeric_qname(qtype, idx) and numeric_default == "object" and not is_unitless_literal(pname, pname_raw):\n                    # If no unit pair in schema, record for warning\n                    if not has_unit_pair(name):\n                        stats["numeric_without_unit_pair"].add(pname_raw)\n                    add_prop(props, pname, "object", domain, None, get_doc(el), meta={"measurement_like": True})\n                else:\n                    add_prop(props, pname, "datatype", domain, val, get_doc(el))\n            continue\n\n        # inline simpleType?\n        st = el.find(f"{XS}simpleType")\n        if st is not None:\n            restr = st.find(f"{XS}restriction")\n            base = restr.get("base") if restr is not None else "xsd:string"\n            enums = [e.get("value") for e in (restr.findall(f"{XS}enumeration") if restr is not None else []) if e.get("value") is not None]\n\n            if enum_as_class and enums:\n                enum_cls = name if name != "Type" else f"{domain}Type"\n                ensure_class(enum_cls)\n                add_prop(props, pname, "object", domain, enum_cls, get_doc(el) or get_doc(st))\n            else:\n                if is_numeric_qname(base, idx) and numeric_default == "object" and not is_unitless_literal(pname, pname_raw):\n                    if not has_unit_pair(name):\n                        stats["numeric_without_unit_pair"].add(pname_raw)\n                    add_prop(props, pname, "object", domain, None, get_doc(el) or get_doc(st), meta={"measurement_like": True})\n                else:\n                    kind, val, is_unknown = resolve_type_kind(base, idx, enum_as_class)\n                    if is_unknown:\n                        stats["unknown_types"].add(base)\n                    add_prop(props, pname, "datatype", domain, val if kind == "datatype" else "xsd:string", get_doc(el) or get_doc(st))\n            continue\n\n        # inline complexType?\n        ct2 = el.find(f"{XS}complexType")\n        if ct2 is not None:\n            ensure_class(name)\n            add_prop(props, pname, "object", domain, name, get_doc(el) or get_doc(ct2))\n            continue\n\n        add_prop(props, pname, "datatype", domain, "xsd:string", get_doc(el))\n\n    # Attributes\n    for at in ct_elem.findall(f".//{XS}attribute"):\n        aname = at.get("name")\n        if not aname:\n            continue\n\n        if skip_id_attributes and aname == "ID":\n            continue\n\n        # Skip unit attributes when paired and configured\n        if skip_unit_properties and is_unit_name(aname) and (aname[:-len(unit_suffix)] in attr_names or aname[:-len(unit_suffix)] in elem_names):\n            continue\n\n        pname, pname_raw = final_prop_name(domain, aname, is_attr=True)\n        qtype = at.get("type")\n\n        if qtype:\n            kind, val, is_unknown = resolve_type_kind(qtype, idx, enum_as_class)\n            if is_unknown:\n                stats["unknown_types"].add(qtype)\n            if kind == "class":\n                ensure_class(val)\n                add_prop(props, pname, "object", domain, val, get_doc(at))\n            else:\n                if is_numeric_qname(qtype, idx) and numeric_default == "object" and not is_unitless_literal(pname, pname_raw):\n                    if not has_unit_pair(aname):\n                        stats["numeric_without_unit_pair"].add(pname_raw)\n                    add_prop(props, pname, "object", domain, None, get_doc(at), meta={"measurement_like": True})\n                else:\n                    add_prop(props, pname, "datatype", domain, val, get_doc(at))\n            continue\n\n        st = at.find(f"{XS}simpleType")\n        if st is not None:\n            restr = st.find(f"{XS}restriction")\n            base = restr.get("base") if restr is not None else "xsd:string"\n            enums = [e.get("value") for e in (restr.findall(f"{XS}enumeration") if restr is not None else []) if e.get("value") is not None]\n\n            if enum_as_class and enums:\n                enum_cls = aname if aname != "Type" else f"{domain}Type"\n                ensure_class(enum_cls)\n                add_prop(props, pname, "object", domain, enum_cls, get_doc(at) or get_doc(st))\n            else:\n                if is_numeric_qname(base, idx) and numeric_default == "object" and not is_unitless_literal(pname, pname_raw):\n                    if not has_unit_pair(aname):\n                        stats["numeric_without_unit_pair"].add(pname_raw)\n                    add_prop(props, pname, "object", domain, None, get_doc(at) or get_doc(st), meta={"measurement_like": True})\n                else:\n                    kind, val, is_unknown = resolve_type_kind(base, idx, enum_as_class)\n                    if is_unknown:\n                        stats["unknown_types"].add(base)\n                    add_prop(props, pname, "datatype", domain, val if kind == "datatype" else "xsd:string", get_doc(at) or get_doc(st))\n            continue\n\n        add_prop(props, pname, "datatype", domain, "xsd:string", get_doc(at))\n\n\n# ----------------------------\n# Emit OWL graph\n# ----------------------------\n\ndef emit_owl_graph(base_ns: str, classes: Dict[str, ClassDef], props: Dict[str, PropDef], rules: Dict[str, Any]) -> Graph:\n    naming = rules.get("naming", {}) or {}\n    owl_cfg = rules.get("owl", {}) or {}\n    meas = rules.get("measurement", {}) or {}\n    ext = rules.get("external", {}) or {}\n\n    name_style = naming.get("name_style", "raw")\n    measurement_range_mode = owl_cfg.get("measurement_range_mode", "omit")\n    value_class_local = meas.get("value_class_local", "QuantityValue")\n\n    g = Graph()\n    NS = Namespace(base_ns)\n\n    g.bind("", NS)\n    g.bind("owl", OWL)\n    g.bind("rdf", RDF)\n    g.bind("rdfs", RDFS)\n    g.bind("xsd", XSD)\n    g.bind("qudt", Namespace("http://qudt.org/schema/qudt#"))\n\n    onto = URIRef(base_ns.rstrip("/") + "/")\n    g.add((onto, RDF.type, OWL.Ontology))\n\n    # Optional helper property declarations\n    if bool(ext.get("emit_rdf_value", True)):\n        g.add((RDF.value, RDF.type, OWL.DatatypeProperty))\n        g.add((RDF.value, RDFS.label, Literal("value", lang="en")))\n\n    if bool(ext.get("emit_qudt_unit", True)):\n        g.add((QUDT_UNIT, RDF.type, OWL.ObjectProperty))\n        g.add((QUDT_UNIT, RDFS.label, Literal("unit", lang="en")))\n\n    value_class_iri = None\n    if measurement_range_mode == "value_class":\n        value_class_iri = NS[encode_name(value_class_local, name_style)]\n        g.add((value_class_iri, RDF.type, OWL.Class))\n        g.add((value_class_iri, RDFS.label, Literal(value_class_local)))\n\n    # Classes\n    for cname, cdef in classes.items():\n        curi = NS[encode_name(cname, name_style)]\n        g.add((curi, RDF.type, OWL.Class))\n        g.add((curi, RDFS.label, Literal(cname)))\n        if cdef.comment:\n            g.add((curi, RDFS.comment, Literal(cdef.comment)))\n        for sup in sorted(cdef.superclasses):\n            g.add((curi, RDFS.subClassOf, NS[encode_name(sup, name_style)]))\n\n    # Properties\n    for pname, pdef in props.items():\n        puri = NS[encode_name(pname, name_style)]\n        g.add((puri, RDF.type, OWL.ObjectProperty if pdef.kind == "object" else OWL.DatatypeProperty))\n        g.add((puri, RDFS.label, Literal(pname)))\n        if pdef.comment:\n            g.add((puri, RDFS.comment, Literal(pdef.comment)))\n\n        for d in sorted(pdef.domains):\n            g.add((puri, RDFS.domain, NS[encode_name(d, name_style)]))\n\n        # Range rules\n        if pdef.kind == "object" and not pdef.ranges:\n            if measurement_range_mode == "thing":\n                g.add((puri, RDFS.range, OWL.Thing))\n            elif measurement_range_mode == "value_class" and value_class_iri is not None:\n                g.add((puri, RDFS.range, value_class_iri))\n            # else omit\n        else:\n            for r in sorted(pdef.ranges):\n                if isinstance(r, str) and r.startswith("xsd:"):\n                    _, local = split_qname(r)\n                    g.add((puri, RDFS.range, getattr(XSD, local, URIRef(str(XSD) + local))))\n                else:\n                    g.add((puri, RDFS.range, NS[encode_name(str(r), name_style)]))\n\n    return g\n\n\n# ----------------------------\n# Verify (optional, rule-driven)\n# ----------------------------\n\ndef _locals_from_subjects(g: Graph, rdf_type: URIRef, base_ns: str) -> Set[str]:\n    out: Set[str] = set()\n    for s in g.subjects(RDF.type, rdf_type):\n        ss = str(s)\n        if ss.startswith(base_ns):\n            out.add(ss[len(base_ns):])\n    return out\n\ndef verify_against(reference_ttl: Path, generated_graph: Graph, base_ns: str) -> Dict[str, Any]:\n    ref = Graph()\n    ref.parse(str(reference_ttl), format="turtle")\n    gen = generated_graph\n\n    cls_ref = _locals_from_subjects(ref, OWL.Class, base_ns)\n    op_ref = _locals_from_subjects(ref, OWL.ObjectProperty, base_ns)\n    dp_ref = _locals_from_subjects(ref, OWL.DatatypeProperty, base_ns)\n\n    cls_gen = _locals_from_subjects(gen, OWL.Class, base_ns)\n    op_gen = _locals_from_subjects(gen, OWL.ObjectProperty, base_ns)\n    dp_gen = _locals_from_subjects(gen, OWL.DatatypeProperty, base_ns)\n\n    def summary(a: Set[str], b: Set[str]) -> Dict[str, int]:\n        inter = a & b\n        return {\n            "ref": len(a),\n            "gen": len(b),\n            "intersection": len(inter),\n            "ref_only": len(a - b),\n            "gen_only": len(b - a),\n        }\n\n    mismatch_obj_to_data = sorted(list(op_ref & dp_gen))\n    mismatch_data_to_obj = sorted(list(dp_ref & op_gen))\n\n    return {\n        "classes": summary(cls_ref, cls_gen),\n        "object_properties": summary(op_ref, op_gen),\n        "datatype_properties": summary(dp_ref, dp_gen),\n        "mismatch_ref_object_gen_datatype_count": len(mismatch_obj_to_data),\n        "mismatch_ref_datatype_gen_object_count": len(mismatch_data_to_obj),\n        "samples": {\n            "mismatch_ref_object_gen_datatype": mismatch_obj_to_data[:50],\n            "mismatch_ref_datatype_gen_object": mismatch_data_to_obj[:50],\n        }\n    }\n\n\n# ----------------------------\n# Warnings based on extraction stats (rule improvement prompts)\n# ----------------------------\n\ndef build_rule_suggestions_from_stats(stats: Dict[str, Any], rules: Dict[str, Any]) -> List[RuleIssue]:\n    issues: List[RuleIssue] = []\n    numeric_default = stats.get("numeric_default", "object")\n    unitless_missing = stats.get("numeric_without_unit_pair", [])\n\n    if numeric_default == "object" and unitless_missing:\n        # [XV-010] suggest to consider unitless literal rules\n        # Provide a patch that appends a few candidates; user can decide.\n        # We don\'t want to dump huge list into patch; keep top N.\n        top = unitless_missing[:30]\n        issues.append(RuleIssue(\n            code="XV-010",\n            level="WARN",\n            message="数値プロパティ（numeric）が検出されましたが、Unitペアが見つからない候補があります。単位なし(literal)にするならルールで指定してください。",\n            missing_keys=["measurement.unitless_literal_properties (candidate)"],\n            suggested_patch={"measurement": {"unitless_literal_properties": top}},\n            details={"candidates_count": len(unitless_missing), "candidates_sample": top}\n        ))\n\n    unknown_types = stats.get("unknown_types", [])\n    if unknown_types:\n        issues.append(RuleIssue(\n            code="XV-030",\n            level="WARN",\n            message="スキーマ集合内で解決できない型参照（unknown QName）がありました。必要なら型の扱いをルールで明示してください。",\n            missing_keys=["(optional) type_mappings"],\n            suggested_patch={"type_mappings": {t: "xsd:string" for t in unknown_types[:10]}},\n            details={"unknown_types_count": len(unknown_types), "unknown_types_sample": unknown_types[:20]}\n        ))\n\n    unitless_not_found = stats.get("unitless_literal_not_found", [])\n    if unitless_not_found:\n        issues.append(RuleIssue(\n            code="XV-012",\n            level="WARN",\n            message="measurement.unitless_literal_properties に指定されたプロパティが、生成されたプロパティ名として見つかりませんでした（命名規則/文脈指定の違いの可能性）。",\n            missing_keys=[],\n            suggested_patch={},\n            details={"not_found": unitless_not_found[:50], "not_found_count": len(unitless_not_found)}\n        ))\n\n    return issues\n\n\n# ----------------------------\n# Rule patch output\n# ----------------------------\n\ndef write_todo_patch(path: Path, patch: Dict[str, Any]) -> None:\n    ext = path.suffix.lower()\n    if ext == ".json":\n        path.write_text(json.dumps(patch, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n    else:\n        write_rules_tsv(path, patch, include_header=True)\n\n\n# ----------------------------\n# CLI\n# ----------------------------\n\ndef default_out_path(input_path: Path) -> Path:\n    if input_path.is_dir():\n        return input_path / "schema.owl.ttl"\n    return input_path.with_suffix(".owl.ttl")\n\ndef main():\n    ap = argparse.ArgumentParser(description="XML-RDF Convertor v1.0 (schema): XSD -> OWL (Turtle) converter with JSON/TSV rules + validation warnings")\n    ap.add_argument("input", nargs="?", default="", help="XSD file or directory")\n    ap.add_argument("-o", "--out", default="", help="Output OWL Turtle path (default: <input>.owl.ttl)")\n    ap.add_argument("--rules", default="", help="Rule file (.json or .tsv). If omitted, defaults are used (warnings may appear).")\n    ap.add_argument("--init-rules", default="", help="Write default rules (including defaults) to this path (.json/.tsv) and exit.")\n    ap.add_argument("--dump-effective-rules", default="", help="Write effective rules (defaults + overrides) to this path (.json/.tsv) and exit.")\n    ap.add_argument("--dry-run", action="store_true", help="Only print effective config + warnings; do not generate OWL.")\n    args = ap.parse_args()\n\n    # Init rules output and exit\n    if args.init_rules:\n        out = Path(args.init_rules)\n        ext = out.suffix.lower()\n        if ext == ".json":\n            out.write_text(json.dumps(DEFAULT_RULES, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n        else:\n            write_rules_tsv(out, DEFAULT_RULES, include_header=True)\n        print(f"OK: wrote default rules to {out}")\n        return\n\n    # Load rules (override)\n    overrides, rules_format = load_rules_file(args.rules) if args.rules else ({}, "none")\n\n    # Merge defaults + overrides\n    eff = compute_effective_rules(DEFAULT_RULES, overrides)\n\n    # Validate and normalize\n    eff, issues = validate_rules(eff, rules_format=rules_format)\n\n    quiet = bool((eff.get("logging", {}) or {}).get("quiet", False))\n    print_effective_mode = str((eff.get("logging", {}) or {}).get("print_effective_config", "summary") or "summary").lower()\n    if quiet:\n        print_effective_mode = "none"\n\n    if print_effective_mode not in ("summary", "full", "none"):\n        print_effective_mode = "summary"\n\n    if not quiet:\n        print_effective_config(eff, print_effective_mode)\n\n    # Print rule issues (missing/insufficient)\n    validation_mode = str((eff.get("validation", {}) or {}).get("mode", "warn") or "warn").lower()\n    print_patches = bool((eff.get("validation", {}) or {}).get("print_patches", True))\n    todo_patch_path = str((eff.get("validation", {}) or {}).get("todo_patch_path", "") or "")\n\n    if validation_mode in ("warn", "strict") and not quiet:\n        print_issues(issues, rules_format=rules_format if rules_format != "none" else "json", print_patches=print_patches)\n\n    # strict mode: abort on ERROR\n    if validation_mode == "strict":\n        if any(i.level == "ERROR" for i in issues):\n            raise SystemExit("Aborting due to missing required rules (strict mode).")\n\n    # Dump effective rules and exit\n    if args.dump_effective_rules:\n        out = Path(args.dump_effective_rules)\n        ext = out.suffix.lower()\n        if ext == ".json":\n            out.write_text(json.dumps(eff, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n        else:\n            write_rules_tsv(out, eff, include_header=True)\n        print(f"OK: wrote effective rules to {out}")\n        return\n\n    # Dry-run\n    if args.dry_run:\n        print("Dry-run: no OWL generated.")\n        return\n\n\n    if not args.input:\n        raise SystemExit("Input XSD path is required unless you use --init-rules or --dump-effective-rules.")\n    input_path = Path(args.input)\n\n    # Determine output\n    out_path = Path(args.out) if args.out else default_out_path(input_path)\n\n    # Discover XSD set\n    follow_includes = bool((eff.get("input", {}) or {}).get("follow_includes", False))\n    xsd_files, unresolved = discover_xsd_set(input_path, follow_includes=follow_includes)\n    if not xsd_files:\n        raise SystemExit("No XSD files found.")\n\n    if unresolved and not quiet:\n        print(f"WARN: unresolved schemaLocation = {len(unresolved)} (include/import). Example: {unresolved[:3]}")\n\n    # Build index and defs\n    idx = build_index(xsd_files)\n    classes, props, stats = build_defs(xsd_files, idx, eff)\n\n    # Additional suggestions based on extraction stats\n    suggestions = build_rule_suggestions_from_stats(stats, eff)\n    if validation_mode in ("warn", "strict") and suggestions and not quiet:\n        print_issues(suggestions, rules_format=rules_format if rules_format != "none" else "json", print_patches=print_patches)\n\n    # Write TODO patch if configured (merge suggested patches)\n    if todo_patch_path:\n        patch: Dict[str, Any] = {}\n        # Combine patches from base validation issues and extraction suggestions\n        for iss in issues + suggestions:\n            if iss.suggested_patch:\n                deep_update(patch, iss.suggested_patch)\n        if patch:\n            write_todo_patch(Path(todo_patch_path), patch)\n            if not quiet:\n                print(f"OK: wrote TODO patch to {todo_patch_path}")\n\n    if validation_mode == "strict":\n        # in strict, you might also choose to abort on some WARN; here we only abort on ERROR above.\n        pass\n\n    # Emit OWL\n    base_ns = str((eff.get("project", {}) or {}).get("base_ns", PLACEHOLDER_BASE_NS))\n    g = emit_owl_graph(base_ns, classes, props, eff)\n\n    data = g.serialize(format="turtle")\n    out_path.write_bytes(data if isinstance(data, (bytes, bytearray)) else data.encode("utf-8"))\n\n    if not quiet:\n        print(f"OK: wrote OWL Turtle to {out_path}")\n        print(f"Stats: classes={len(classes)}, properties={len(props)}")\n        if stats.get("numeric_without_unit_pair"):\n            print(f"Hint: numeric properties without unit pair candidates: {len(stats[\'numeric_without_unit_pair\'])} (see warnings)")\n\n    # Optional verify\n    verify_cfg = eff.get("verify", {}) or {}\n    if bool(verify_cfg.get("enabled", False)):\n        ref_path = str(verify_cfg.get("reference_ttl", "") or "").strip()\n        if ref_path:\n            rep = verify_against(Path(ref_path), g, base_ns)\n            if not quiet:\n                print("\\n=== Verify summary ===")\n                print(json.dumps(rep, ensure_ascii=False, indent=2))\n            # optional report outputs\n            rjson = str(verify_cfg.get("report_json", "") or "").strip()\n            rcsv = str(verify_cfg.get("report_csv", "") or "").strip()\n            if rjson:\n                Path(rjson).write_text(json.dumps(rep, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n            if rcsv:\n                # minimal csv\n                import csv\n                with open(rcsv, "w", newline="", encoding="utf-8") as f:\n                    w = csv.writer(f)\n                    w.writerow(["category", "ref", "gen", "intersection", "ref_only", "gen_only"])\n                    for cat in ("classes", "object_properties", "datatype_properties"):\n                        row = rep[cat]\n                        w.writerow([cat, row["ref"], row["gen"], row["intersection"], row["ref_only"], row["gen_only"]])\n\n        elif not quiet:\n            print("WARN: verify.enabled=true but verify.reference_ttl is empty. Skipping verify.")\n\n'
_INSTANCE_SOURCE = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\n"""\nxml_rdf_convertor_instance.py\n\nXML-RDF Convertor (Version 1.0)\n\nGeneric XML (instance) -> RDF (ABox) converter driven by:\n  - XSD schema (for typing: complex/simple, numeric, enum, unit types)\n  - user rule file (JSON or TSV) for policies and URI patterns\n\nImplements the three core capabilities requested:\n  1) Instance conversion with stable instance URIs + parent/child structure, incl. Ref resolution\n  2) Enum values mapped to URI resources (ObjectProperty), with normalization and optional mapping table\n  3) Unit-bearing numeric values modeled as objects (quantity nodes) rather than literals\n     (rdf:value + qudt:unit). Unitless numeric values can be forced to literals via rules.\n\nNotes:\n  - This script complements xml_rdf_convertor_schema.py (XSD->OWL vocabulary/TBox).\n  - This script produces instance RDF that *uses* the vocabulary namespace (project.base_ns).\n\nDependencies:\n  - rdflib (pip install rdflib)\n  - xml.etree.ElementTree (stdlib)\n\nTypical usage:\n  python xml_rdf_convertor_instance.py schema.xsd instance.xml --rules rules.tsv -o instances.ttl\n\nRule formats:\n  - JSON: nested dict\n  - TSV : key<TAB>value (supports list append key[] and map key[subkey])\n\nDesign goals:\n  - Minimal CLI options; most behavior in rule file\n  - Print effective config (including defaults)\n  - Warn about missing/insufficient rules and show actionable patches\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport copy\nimport json\nimport re\nfrom dataclasses import dataclass, field\nfrom pathlib import Path\nfrom typing import Any, Dict, Iterable, List, Optional, Set, Tuple\n\nimport urllib.parse\nimport xml.etree.ElementTree as ET\n\nfrom rdflib import BNode, Graph, Literal, Namespace, URIRef\nfrom rdflib.namespace import RDF, RDFS, OWL, XSD\n\n\n# ----------------------------\n# XML Schema namespace\n# ----------------------------\nXS_NS = "http://www.w3.org/2001/XMLSchema"\nXS = "{%s}" % XS_NS\n\nSPEC_ID = "xml-rdf-convertor-instance-1.0"\n\nPROGRAM_NAME = "XML-RDF Convertor"\nPROGRAM_VERSION = "1.0"\n__version__ = PROGRAM_VERSION\n\nDCTERMS = Namespace("http://purl.org/dc/terms/")\nQUDT = Namespace("http://qudt.org/schema/qudt#")\nQUDT_UNIT = QUDT.unit\n\nPLACEHOLDER_BASE_NS = "http://example.org/ontology/"\nPLACEHOLDER_INSTANCE_NS = "http://example.org/instance/"\n\n\n# ----------------------------\n# Defaults (superset-friendly)\n# ----------------------------\n\nDEFAULT_RULES: Dict[str, Any] = {\n    "version": 1,\n\n    # Vocabulary (TBox) namespace\n    "project": {\n        "base_ns": "",\n        "name": ""\n    },\n\n    # Instance (ABox) namespace and URI policy\n    "instance": {\n        "base_ns": "",\n\n        # Placeholders: {base}, {class}, {id}\n        # Example: "{base}{class}/{id}"\n        "uri_pattern": "{base}{class}/{id}",\n\n        # Attribute name used as identifier when present\n        "id_attribute": "ID",\n\n        # If no ID attribute exists, create a synthetic id like "{class}:{n}"\n        "auto_id_prefix_mode": "class",  # class|fixed\n        "auto_id_prefix_fixed": "obj",\n        "auto_id_start": 0,\n\n        # If true, also attach dcterms:identifier with the original ID value (when present)\n        "emit_identifier_triple": True,\n        "identifier_predicate": str(DCTERMS.identifier),\n\n        # If true, create placeholder resources for referenced IDs not yet defined\n        "allow_forward_refs": True,\n    },\n\n    "input": {\n        "follow_includes": False,\n    },\n\n    "naming": {\n        "name_style": "raw",  # raw|quote|slug (applies to generated local names in vocabulary and instance URIs)\n        "lower_first_properties": True,\n        "contextual_properties": False,\n    },\n\n    "ref": {\n        # Detect reference elements like DetectorRef, ChannelRef, ...\n        "element_suffix": "Ref",\n        "id_attribute": "ID",\n\n        # Property name: strip suffix? DetectorRef -> detector (True) vs detectorRef (False)\n        "strip_suffix_for_property": True,\n\n        # Class name of target: strip suffix? DetectorRef -> Detector\n        "strip_suffix_for_class": True,\n    },\n\n    "enum": {\n        # If true, represent enum values as URI resources (ObjectProperty).\n        # If false, keep enum values as literals.\n        "as_uri": True,\n\n        # Template for enum value URI:\n        # Placeholders: {base_ns}, {type}, {value}\n        # Example -> http://.../ome_core/AcquisitionMode#wideField\n        "uri_template": "{base_ns}{type}#{value}",\n\n        # Normalize enum value to IRI fragment\n        "value_normalization": "lower_first",  # lower_first|lower|raw|slug|quote\n        "leading_digit_prefix": "v",\n\n        # Optional: explicit mapping tables\n        # - Global map: enum.value_uri_map[RAW_VALUE] = FULL_URI\n        "value_uri_map": {},\n        # - By-type map: enum.value_uri_map_by_type[TypeName][RAW_VALUE] = FULL_URI\n        "value_uri_map_by_type": {},\n\n        # Policy when value not in XSD enumeration list (if list exists):\n        # warn_uri: warn and still mint URI\n        # literal : warn and use literal\n        # strict  : abort\n        "unknown_value_policy": "warn_uri",\n    },\n\n    "measurement": {\n        # Default modelling for numeric values:\n        # object => quantity node with rdf:value (+ qudt:unit if available)\n        # datatype => numeric literal\n        "numeric_default": "object",\n\n        # Exceptions: force literal (unitless numeric)\n        "unitless_literal_properties": [],\n        "unitless_literal_property_patterns": [],\n\n        # Unit pairing and emission\n        "unit_suffix": "Unit",\n        "skip_unit_properties": True,\n\n        # Where to mint unit URIs when no mapping is provided\n        "unit_base_ns": "",  # if empty, uses project.base_ns + "unit/"\n\n        # Optional mapping of unit lexeme to URI (global)\n        # e.g. "µm": "http://.../unit/Length#um"\n        "unit_uri_map": {},\n\n        # Template for unit URI when map doesn\'t match:\n        # Placeholders: {unit_base}, {kind}, {unit}\n        # If kind is unknown, "Unit" is used.\n        "unit_uri_template": "{unit_base}{kind}#{unit}",\n\n        # Normalize unit token for use in URI\n        "unit_normalization": "quote",  # quote|raw|slug\n\n        # Quantity node typing:\n        # - default class URI for quantity nodes (if empty, omit rdf:type for quantity nodes)\n        "value_class_uri": "",  # e.g. "http://.../ome_core/QuantityValue" or external PATO class\n        # - property-specific quantity class URIs (full URI strings)\n        "quantity_class_by_property": {},\n\n        # Whether to reuse identical quantity nodes (value, unit, qclass) across the graph\n        "deduplicate_quantity_nodes": True,\n    },\n\n    "validation": {\n        "mode": "warn",  # force|warn|strict\n        "print_patches": True,\n        "todo_patch_path": "",\n    },\n\n    "logging": {\n        "print_effective_config": "summary",  # summary|full|none\n        "quiet": False,\n    },\n}\n\n\n# ----------------------------\n# Helpers: name encoding\n# ----------------------------\n\ndef _slug(s: str) -> str:\n    import unicodedata\n    s = unicodedata.normalize("NFKC", s).strip().lower()\n    s = re.sub(r"\\s+", "-", s)\n    s = re.sub(r"[^\\w\\-]", "", s)\n    return s or "unnamed"\n\ndef encode_name(name: str, style: str) -> str:\n    name = (name or "").strip()\n    if style == "quote":\n        return urllib.parse.quote(name, safe="")\n    if style == "slug":\n        return _slug(name)\n    return name\n\ndef local_name(tag: str) -> str:\n    if tag.startswith("{"):\n        return tag.split("}", 1)[1]\n    return tag\n\ndef lower_first(name: str) -> str:\n    if not name:\n        return name\n    if len(name) == 1:\n        return name.lower()\n    return name[0].lower() + name[1:]\n\ndef split_qname(qname: str) -> Tuple[str, str]:\n    if qname and ":" in qname:\n        p, l = qname.split(":", 1)\n        return p, l\n    return "", qname or ""\n\n\n# ----------------------------\n# TSV rule file parsing/writing\n# (copied/adapted from xml_rdf_convertor_schema.py)\n# ----------------------------\n\ndef parse_scalar(value: str) -> Any:\n    v = value.strip()\n    if v == "":\n        return ""\n    low = v.lower()\n    if low in ("true", "false"):\n        return low == "true"\n    if re.fullmatch(r"[+-]?\\d+", v):\n        try:\n            return int(v)\n        except ValueError:\n            pass\n    if re.fullmatch(r"[+-]?\\d+\\.\\d+", v):\n        try:\n            return float(v)\n        except ValueError:\n            pass\n    if (v.startswith("[") and v.endswith("]")) or (v.startswith("{") and v.endswith("}")):\n        try:\n            return json.loads(v)\n        except json.JSONDecodeError:\n            return v\n    return v\n\n_KEY_ARRAY = re.compile(r"^(?P<path>.+)\\[\\]$")\n_KEY_MAP = re.compile(r"^(?P<path>.+)\\[(?P<subkey>.+)\\]$")\n\ndef set_by_dotted_path(obj: Dict[str, Any], dotted: str, value: Any) -> None:\n    parts = dotted.split(".")\n    cur: Dict[str, Any] = obj\n    for p in parts[:-1]:\n        if p not in cur or not isinstance(cur[p], dict):\n            cur[p] = {}\n        cur = cur[p]\n    cur[parts[-1]] = value\n\ndef get_by_dotted_path(obj: Dict[str, Any], dotted: str) -> Any:\n    cur: Any = obj\n    for p in dotted.split("."):\n        if not isinstance(cur, dict) or p not in cur:\n            return None\n        cur = cur[p]\n    return cur\n\ndef load_rules_tsv(path: Path) -> Dict[str, Any]:\n    rules: Dict[str, Any] = {}\n    text = path.read_text(encoding="utf-8-sig")\n    for raw in text.splitlines():\n        line = raw.strip("\\n\\r")\n        if not line.strip():\n            continue\n        if line.lstrip().startswith("#"):\n            continue\n        parts = line.split("\\t")\n        if len(parts) < 2:\n            continue\n        key = parts[0].strip()\n        val = parse_scalar(parts[1])\n        if key == "":\n            continue\n\n        m_arr = _KEY_ARRAY.match(key)\n        if m_arr:\n            base = m_arr.group("path")\n            existing = get_by_dotted_path(rules, base)\n            if existing is None or not isinstance(existing, list):\n                set_by_dotted_path(rules, base, [])\n                existing = get_by_dotted_path(rules, base)\n            existing.append(val)\n            continue\n\n        m_map = _KEY_MAP.match(key)\n        if m_map:\n            base = m_map.group("path")\n            subkey = m_map.group("subkey")\n            existing = get_by_dotted_path(rules, base)\n            if existing is None or not isinstance(existing, dict):\n                set_by_dotted_path(rules, base, {})\n                existing = get_by_dotted_path(rules, base)\n            existing[subkey] = val\n            continue\n\n        set_by_dotted_path(rules, key, val)\n\n    return rules\n\ndef flatten_for_tsv(obj: Any, prefix: str = "") -> List[Tuple[str, Any]]:\n    out: List[Tuple[str, Any]] = []\n    if isinstance(obj, dict):\n        for k in sorted(obj.keys()):\n            out.extend(flatten_for_tsv(obj[k], f"{prefix}.{k}" if prefix else k))\n        return out\n    if isinstance(obj, list):\n        key = prefix\n        if not obj:\n            out.append((key, []))\n        else:\n            for item in obj:\n                out.append((key + "[]", item))\n        return out\n    out.append((prefix, obj))\n    return out\n\ndef tsv_value_repr(v: Any) -> str:\n    if isinstance(v, bool):\n        return "true" if v else "false"\n    if isinstance(v, (int, float)):\n        return str(v)\n    if isinstance(v, (list, dict)):\n        return json.dumps(v, ensure_ascii=False)\n    return "" if v is None else str(v)\n\ndef write_rules_tsv(path: Path, rules: Dict[str, Any], *, include_header: bool = True) -> None:\n    lines: List[str] = []\n    if include_header:\n        lines.append("# xml2rdf rules (TSV)")\n        lines.append(f"# spec\\t{SPEC_ID}")\n        lines.append("# format:\\tkey<TAB>value<TAB>(optional comment)")\n        lines.append("# arrays:\\tkey[] value (append)")\n        lines.append("# maps:\\tkey[subkey] value")\n        lines.append("#")\n\n    flat = flatten_for_tsv(rules)\n    for k, v in flat:\n        lines.append(f"{k}\\t{tsv_value_repr(v)}")\n    path.write_text("\\n".join(lines) + "\\n", encoding="utf-8")\n\ndef load_rules_file(path: Optional[str]) -> Tuple[Dict[str, Any], str]:\n    if not path:\n        return {}, "none"\n    p = Path(path)\n    if not p.exists():\n        raise FileNotFoundError(f"Rules file not found: {path}")\n    ext = p.suffix.lower()\n    if ext == ".json":\n        return json.loads(p.read_text(encoding="utf-8-sig")), "json"\n    return load_rules_tsv(p), "tsv"\n\ndef deep_update(dst: Dict[str, Any], src: Dict[str, Any]) -> None:\n    for k, v in src.items():\n        if isinstance(v, dict) and isinstance(dst.get(k), dict):\n            deep_update(dst[k], v)  # type: ignore[index]\n        else:\n            dst[k] = copy.deepcopy(v)\n\ndef compute_effective_rules(defaults: Dict[str, Any], overrides: Dict[str, Any]) -> Dict[str, Any]:\n    eff = copy.deepcopy(defaults)\n    deep_update(eff, overrides)\n    return eff\n\n\n# ----------------------------\n# Validation issues\n# ----------------------------\n\n@dataclass\nclass RuleIssue:\n    code: str\n    level: str  # WARN|ERROR\n    message: str\n    missing_keys: List[str] = field(default_factory=list)\n    suggested_patch: Dict[str, Any] = field(default_factory=dict)\n    details: Dict[str, Any] = field(default_factory=dict)\n\ndef format_patch_json(patch: Dict[str, Any]) -> str:\n    return json.dumps(patch, ensure_ascii=False, indent=2)\n\ndef format_patch_tsv(patch: Dict[str, Any]) -> str:\n    return "\\n".join([f"{k}\\t{tsv_value_repr(v)}" for k, v in flatten_for_tsv(patch)])\n\ndef validate_rules(effective: Dict[str, Any], *, rules_format: str) -> Tuple[Dict[str, Any], List[RuleIssue]]:\n    eff = copy.deepcopy(effective)\n    issues: List[RuleIssue] = []\n\n    # project.base_ns\n    base_ns = str(((eff.get("project", {}) or {}).get("base_ns", "") or "")).strip()\n    if not base_ns:\n        issues.append(RuleIssue(\n            code="XI-001",\n            level="ERROR",\n            message="project.base_ns が未指定です。語彙（クラス/プロパティ）URIのため base_ns が必要です。暫定的にプレースホルダで変換を続行します。",\n            missing_keys=["project.base_ns"],\n            suggested_patch={"project": {"base_ns": "http://your.example.org/ontology/"}},\n        ))\n        base_ns = PLACEHOLDER_BASE_NS\n    if not base_ns.endswith("/"):\n        issues.append(RuleIssue(\n            code="XI-002",\n            level="WARN",\n            message="project.base_ns が \'/\' で終わっていません。正規化のため末尾に \'/\' を付与して使用します。",\n            suggested_patch={"project": {"base_ns": base_ns + "/"}},\n            details={"original": base_ns},\n        ))\n        base_ns = base_ns + "/"\n    eff.setdefault("project", {})["base_ns"] = base_ns  # type: ignore[index]\n\n    # instance.base_ns\n    inst_ns = str(((eff.get("instance", {}) or {}).get("base_ns", "") or "")).strip()\n    if not inst_ns:\n        issues.append(RuleIssue(\n            code="XI-003",\n            level="WARN",\n            message="instance.base_ns が未指定です。個体URIのため base_ns が必要です。暫定的に project.base_ns + \'instance/\' を使用します。",\n            missing_keys=["instance.base_ns"],\n            suggested_patch={"instance": {"base_ns": base_ns + "instance/"}},\n        ))\n        inst_ns = base_ns + "instance/"\n    if not inst_ns.endswith("/"):\n        issues.append(RuleIssue(\n            code="XI-004",\n            level="WARN",\n            message="instance.base_ns が \'/\' で終わっていません。正規化のため末尾に \'/\' を付与して使用します。",\n            suggested_patch={"instance": {"base_ns": inst_ns + "/"}},\n            details={"original": inst_ns},\n        ))\n        inst_ns = inst_ns + "/"\n    eff.setdefault("instance", {})["base_ns"] = inst_ns  # type: ignore[index]\n\n    # validation.mode\n    mode = str(((eff.get("validation", {}) or {}).get("mode", "warn") or "warn")).lower()\n    if mode not in ("force", "warn", "strict"):\n        issues.append(RuleIssue(\n            code="XI-005",\n            level="WARN",\n            message=f\'validation.mode="{mode}" は未知です。warn として扱います。\',\n            suggested_patch={"validation": {"mode": "warn"}},\n        ))\n        mode = "warn"\n    eff.setdefault("validation", {})["mode"] = mode  # type: ignore[index]\n\n    # measurement.numeric_default\n    nd = str(((eff.get("measurement", {}) or {}).get("numeric_default", "object") or "object")).lower()\n    if nd not in ("object", "datatype"):\n        issues.append(RuleIssue(\n            code="XI-006",\n            level="WARN",\n            message=f\'measurement.numeric_default="{nd}" は未知です。object として扱います。\',\n            suggested_patch={"measurement": {"numeric_default": "object"}},\n        ))\n        nd = "object"\n    eff.setdefault("measurement", {})["numeric_default"] = nd  # type: ignore[index]\n\n    # enum\n    uvp = str(((eff.get("enum", {}) or {}).get("unknown_value_policy", "warn_uri") or "warn_uri")).lower()\n    if uvp not in ("warn_uri", "literal", "strict"):\n        issues.append(RuleIssue(\n            code="XI-007",\n            level="WARN",\n            message=f\'enum.unknown_value_policy="{uvp}" は未知です。warn_uri として扱います。\',\n            suggested_patch={"enum": {"unknown_value_policy": "warn_uri"}},\n        ))\n        uvp = "warn_uri"\n    eff.setdefault("enum", {})["unknown_value_policy"] = uvp  # type: ignore[index]\n\n    # measurement.unit_base_ns default\n    meas = eff.get("measurement", {}) or {}\n    unit_base = str(meas.get("unit_base_ns", "") or "").strip()\n    if not unit_base:\n        unit_base = base_ns + "unit/"\n        eff.setdefault("measurement", {})["unit_base_ns"] = unit_base  # type: ignore[index]\n    if not unit_base.endswith("/"):\n        unit_base = unit_base + "/"\n        eff.setdefault("measurement", {})["unit_base_ns"] = unit_base  # type: ignore[index]\n\n    # runtime note\n    eff.setdefault("runtime", {})["rules_format"] = rules_format  # type: ignore[index]\n\n    return eff, issues\n\ndef print_issues(issues: List[RuleIssue], *, rules_format: str, print_patches: bool = True) -> None:\n    if not issues:\n        return\n    print("\\n=== Rule validation / missing rules ===")\n    for iss in issues:\n        print(f"[{iss.level}][{iss.code}] {iss.message}")\n        if iss.missing_keys:\n            print("  Missing/required keys:")\n            for k in iss.missing_keys:\n                print(f"    - {k}")\n        if print_patches and iss.suggested_patch:\n            print("  Suggested patch:")\n            if rules_format == "tsv":\n                print(format_patch_tsv(iss.suggested_patch))\n            else:\n                print(format_patch_json(iss.suggested_patch))\n        if iss.details:\n            print("  Details:")\n            for k, v in iss.details.items():\n                print(f"    {k}: {v}")\n    print("=== End of rule validation ===\\n")\n\n\n# ----------------------------\n# Effective config display\n# ----------------------------\n\ndef print_effective_config(eff: Dict[str, Any], mode: str) -> None:\n    if mode == "none":\n        return\n    proj = eff.get("project", {}) or {}\n    inst = eff.get("instance", {}) or {}\n    print("\\n=== Effective conversion configuration (defaults included) ===")\n    print(f"{PROGRAM_NAME} {PROGRAM_VERSION}")\n    print(f"Spec: {SPEC_ID}")\n    if proj.get("name"):\n        print(f"Project: {proj.get(\'name\')}")\n    print(f"Vocabulary base_ns: {proj.get(\'base_ns\')}")\n    print(f"Instance base_ns  : {inst.get(\'base_ns\')}")\n    if mode == "full":\n        print(json.dumps(eff, ensure_ascii=False, indent=2))\n        print("\\n=== End effective configuration ===\\n")\n        return\n    # summary\n    for sec in ("instance", "naming", "ref", "enum", "measurement", "validation", "logging", "input"):\n        if sec in eff:\n            print(f"\\n[{sec}]")\n            section = eff.get(sec, {}) or {}\n            if isinstance(section, dict):\n                for k in sorted(section.keys()):\n                    v = section[k]\n                    if isinstance(v, list):\n                        print(f"  {k}: list(len={len(v)})" + (f" {v[:8]}..." if len(v) > 8 else f" {v}"))\n                    elif isinstance(v, dict):\n                        print(f"  {k}: dict(len={len(v)})")\n                    else:\n                        print(f"  {k}: {v}")\n            else:\n                print(f"  {section}")\n    print("\\n=== End effective configuration ===\\n")\n\n\n# ----------------------------\n# XSD discovery (include/import)\n# ----------------------------\n\ndef iter_xsd_files(path: Path) -> Iterable[Path]:\n    if path.is_file():\n        yield path\n    else:\n        for p in sorted(path.rglob("*.xsd")):\n            yield p\n\ndef extract_schema_locations(xsd_file: Path) -> List[str]:\n    locs: List[str] = []\n    for _, elem in ET.iterparse(str(xsd_file), events=("end",)):\n        if elem.tag in (XS + "include", XS + "import"):\n            loc = elem.get("schemaLocation")\n            if loc:\n                locs.append(loc)\n        elem.clear()\n    return locs\n\ndef discover_xsd_set(input_path: Path, follow_includes: bool) -> Tuple[List[Path], List[Tuple[Path, str]]]:\n    unresolved: List[Tuple[Path, str]] = []\n    if input_path.is_dir():\n        files = list(iter_xsd_files(input_path))\n        return files, unresolved\n\n    start = input_path.resolve()\n    if not follow_includes:\n        return [start], unresolved\n\n    seen: Set[Path] = set()\n    queue: List[Path] = [start]\n\n    while queue:\n        f = queue.pop(0).resolve()\n        if f in seen:\n            continue\n        if not f.exists():\n            continue\n        seen.add(f)\n\n        for loc in extract_schema_locations(f):\n            cand = (f.parent / loc).resolve()\n            if cand.exists() and cand.suffix.lower() == ".xsd":\n                if cand not in seen:\n                    queue.append(cand)\n            else:\n                unresolved.append((f, loc))\n\n    return sorted(seen), unresolved\n\n\n# ----------------------------\n# Schema index\n# ----------------------------\n\nNUMERIC_XSD_TYPES = {\n    "decimal","float","double",\n    "integer","nonPositiveInteger","negativeInteger","long","int","short","byte",\n    "nonNegativeInteger","unsignedLong","unsignedInt","unsignedShort","unsignedByte","positiveInteger"\n}\n\nBOOLEAN_XSD_TYPES = {"boolean"}\nDATETIME_XSD_TYPES = {"dateTime", "date", "time"}\nANYURI_XSD_TYPES = {"anyURI"}\n\n@dataclass\nclass SimpleTypeDecl:\n    name: str\n    base_qname: Optional[str] = None\n    enumerations: List[str] = field(default_factory=list)\n\n@dataclass\nclass PropDecl:\n    name: str\n    kind: str  # "element"|"attribute"\n    type_qname: Optional[str] = None  # qname or local name\n    ref_name: Optional[str] = None\n    default: Optional[str] = None\n    fixed: Optional[str] = None\n    min_occurs: Optional[str] = None\n    max_occurs: Optional[str] = None\n\n@dataclass\nclass ComplexTypeDecl:\n    name: str\n    base_qname: Optional[str] = None\n    derivation: Optional[str] = None\n    elements: Dict[str, PropDecl] = field(default_factory=dict)\n    attributes: Dict[str, PropDecl] = field(default_factory=dict)\n\n@dataclass\nclass GlobalElementDecl:\n    name: str\n    type_qname: Optional[str] = None\n\n@dataclass\nclass SchemaIndex:\n    simple_types: Dict[str, SimpleTypeDecl] = field(default_factory=dict)\n    complex_types: Dict[str, ComplexTypeDecl] = field(default_factory=dict)\n    global_elements: Dict[str, GlobalElementDecl] = field(default_factory=dict)\n    # cache for resolved complex decls (with inheritance applied)\n    _resolved_complex_cache: Dict[str, ComplexTypeDecl] = field(default_factory=dict)\n\ndef _walk_element_decls(ct_elem: ET.Element) -> Iterable[ET.Element]:\n    def walk(node: ET.Element):\n        for ch in list(node):\n            if ch.tag in (XS + "sequence", XS + "choice", XS + "all", XS + "group"):\n                yield from walk(ch)\n            elif ch.tag == XS + "element":\n                yield ch\n            else:\n                # ignore others\n                continue\n    yield from walk(ct_elem)\n\ndef _parse_inline_simple_type(st: ET.Element) -> Tuple[Optional[str], List[str]]:\n    restr = st.find(f"{XS}restriction")\n    base = restr.get("base") if restr is not None else None\n    enums = []\n    if restr is not None:\n        for e in restr.findall(f"{XS}enumeration"):\n            v = e.get("value")\n            if v is not None:\n                enums.append(v)\n    return base, enums\n\ndef _extract_complex_decl(idx: SchemaIndex, ct_elem: ET.Element, type_name: str, synth_counter: List[int]) -> ComplexTypeDecl:\n    decl = ComplexTypeDecl(name=type_name)\n    # base / derivation\n    ext = ct_elem.find(f".//{XS}extension")\n    if ext is not None and ext.get("base"):\n        decl.base_qname = ext.get("base")\n        decl.derivation = "extension"\n    restr = ct_elem.find(f".//{XS}restriction")\n    if restr is not None and restr.get("base"):\n        decl.base_qname = restr.get("base")\n        decl.derivation = "restriction"\n\n    # attributes\n    for at in ct_elem.findall(f".//{XS}attribute"):\n        aname = at.get("name")\n        if not aname:\n            continue\n        pd = PropDecl(name=aname, kind="attribute")\n        pd.type_qname = at.get("type")\n        pd.default = at.get("default")\n        pd.fixed = at.get("fixed")\n        # inline simpleType\n        if pd.type_qname is None:\n            st = at.find(f"{XS}simpleType")\n            if st is not None:\n                base, enums = _parse_inline_simple_type(st)\n                synth_counter[0] += 1\n                st_name = f"{type_name}__{aname}__AnonSimpleType{ synth_counter[0] }"\n                idx.simple_types[st_name] = SimpleTypeDecl(name=st_name, base_qname=base, enumerations=enums)\n                pd.type_qname = st_name\n            else:\n                pd.type_qname = "xsd:string"\n        decl.attributes[aname] = pd\n\n    # elements\n    for el in _walk_element_decls(ct_elem):\n        ref = el.get("ref")\n        name = el.get("name")\n        if not ref and not name:\n            continue\n        if ref:\n            _, rlocal = split_qname(ref)\n            pd = PropDecl(name=rlocal, kind="element", ref_name=rlocal)\n            pd.min_occurs = el.get("minOccurs")\n            pd.max_occurs = el.get("maxOccurs")\n            decl.elements[rlocal] = pd\n            continue\n\n        pd = PropDecl(name=name, kind="element")\n        pd.type_qname = el.get("type")\n        pd.min_occurs = el.get("minOccurs")\n        pd.max_occurs = el.get("maxOccurs")\n\n        if pd.type_qname is None:\n            # inline simple/complex types\n            st = el.find(f"{XS}simpleType")\n            if st is not None:\n                base, enums = _parse_inline_simple_type(st)\n                synth_counter[0] += 1\n                st_name = f"{type_name}__{name}__AnonSimpleType{ synth_counter[0] }"\n                idx.simple_types[st_name] = SimpleTypeDecl(name=st_name, base_qname=base, enumerations=enums)\n                pd.type_qname = st_name\n            else:\n                ct2 = el.find(f"{XS}complexType")\n                if ct2 is not None:\n                    synth_counter[0] += 1\n                    ct_name = f"{type_name}__{name}__AnonComplexType{ synth_counter[0] }"\n                    idx.complex_types[ct_name] = _extract_complex_decl(idx, ct2, ct_name, synth_counter)\n                    pd.type_qname = ct_name\n                else:\n                    pd.type_qname = "xsd:string"\n\n        decl.elements[name] = pd\n\n    return decl\n\ndef build_schema_index(files: List[Path]) -> SchemaIndex:\n    idx = SchemaIndex()\n    synth_counter = [0]\n\n    for xsd_path in files:\n        tag_stack: List[str] = []\n        for ev, elem in ET.iterparse(str(xsd_path), events=("start", "end")):\n            if ev == "start":\n                tag_stack.append(elem.tag)\n                continue\n\n            parent_tag = tag_stack[-2] if len(tag_stack) >= 2 else None\n\n            # global simpleType\n            if elem.tag == XS + "simpleType" and parent_tag == XS + "schema" and elem.get("name"):\n                name = elem.get("name")\n                st = SimpleTypeDecl(name=name)\n                base = None\n                restr = elem.find(f"{XS}restriction")\n                if restr is not None:\n                    base = restr.get("base")\n                    for e in restr.findall(f"{XS}enumeration"):\n                        v = e.get("value")\n                        if v is not None:\n                            st.enumerations.append(v)\n                st.base_qname = base\n                idx.simple_types[name] = st\n                elem.clear()\n\n            # global complexType\n            if elem.tag == XS + "complexType" and parent_tag == XS + "schema" and elem.get("name"):\n                name = elem.get("name")\n                idx.complex_types[name] = _extract_complex_decl(idx, elem, name, synth_counter)\n                elem.clear()\n\n            # global element\n            if elem.tag == XS + "element" and parent_tag == XS + "schema" and elem.get("name"):\n                name = elem.get("name")\n                ge = GlobalElementDecl(name=name, type_qname=elem.get("type"))\n                # inline types: synth as needed\n                if ge.type_qname is None:\n                    st = elem.find(f"{XS}simpleType")\n                    if st is not None:\n                        base, enums = _parse_inline_simple_type(st)\n                        synth_counter[0] += 1\n                        st_name = f"{name}__AnonSimpleType{ synth_counter[0] }"\n                        idx.simple_types[st_name] = SimpleTypeDecl(name=st_name, base_qname=base, enumerations=enums)\n                        ge.type_qname = st_name\n                    else:\n                        ct = elem.find(f"{XS}complexType")\n                        if ct is not None:\n                            synth_counter[0] += 1\n                            ct_name = f"{name}__AnonComplexType{ synth_counter[0] }"\n                            idx.complex_types[ct_name] = _extract_complex_decl(idx, ct, ct_name, synth_counter)\n                            ge.type_qname = ct_name\n                        else:\n                            ge.type_qname = "xsd:string"\n                idx.global_elements[name] = ge\n                elem.clear()\n\n            if tag_stack:\n                tag_stack.pop()\n\n    return idx\n\ndef resolve_simple_type(idx: SchemaIndex, qname: Optional[str], _seen: Optional[Set[str]] = None) -> Optional[SimpleTypeDecl]:\n    if not qname:\n        return None\n    _seen = _seen or set()\n    if qname in _seen:\n        return None\n    _seen.add(qname)\n    _, local = split_qname(qname)\n    if local in idx.simple_types:\n        return idx.simple_types[local]\n    return None\n\ndef is_numeric_type(idx: SchemaIndex, qname: Optional[str], _seen: Optional[Set[str]] = None) -> bool:\n    if not qname:\n        return False\n    _seen = _seen or set()\n    if qname in _seen:\n        return False\n    _seen.add(qname)\n\n    pfx, local = split_qname(qname)\n    if pfx in ("xsd", "xs"):\n        return local in NUMERIC_XSD_TYPES\n    if local in idx.simple_types:\n        base = idx.simple_types[local].base_qname\n        return is_numeric_type(idx, base, _seen)\n    return False\n\ndef xsd_datatype_uri(idx: SchemaIndex, qname: Optional[str]) -> URIRef:\n    """Best-effort datatype for literals."""\n    if not qname:\n        return XSD.string\n    pfx, local = split_qname(qname)\n    if pfx in ("xsd", "xs"):\n        return getattr(XSD, local, XSD.string)\n    # named simple type -> resolve base\n    if local in idx.simple_types:\n        base = idx.simple_types[local].base_qname\n        return xsd_datatype_uri(idx, base)\n    return XSD.string\n\ndef is_boolean_type(idx: SchemaIndex, qname: Optional[str], _seen: Optional[Set[str]] = None) -> bool:\n    if not qname:\n        return False\n    _seen = _seen or set()\n    if qname in _seen:\n        return False\n    _seen.add(qname)\n    pfx, local = split_qname(qname)\n    if pfx in ("xsd", "xs"):\n        return local in BOOLEAN_XSD_TYPES\n    if local in idx.simple_types:\n        return is_boolean_type(idx, idx.simple_types[local].base_qname, _seen)\n    return False\n\ndef infer_unit_kind_from_type(type_qname: Optional[str]) -> str:\n    """Heuristic: UnitsLength -> Length, UnitsTime -> Time, else Unit."""\n    if not type_qname:\n        return "Unit"\n    _, local = split_qname(type_qname)\n    m = re.match(r"^Units(?P<kind>.+)$", local)\n    if m:\n        return m.group("kind")\n    return "Unit"\n\ndef get_resolved_complex_decl(idx: SchemaIndex, type_qname: Optional[str]) -> Optional[ComplexTypeDecl]:\n    if not type_qname:\n        return None\n    _, local = split_qname(type_qname)\n    if local in idx._resolved_complex_cache:\n        return idx._resolved_complex_cache[local]\n    if local not in idx.complex_types:\n        return None\n\n    base_decl = idx.complex_types[local]\n    resolved = ComplexTypeDecl(name=base_decl.name, base_qname=base_decl.base_qname, derivation=base_decl.derivation)\n    # start with own\n    resolved.elements.update(base_decl.elements)\n    resolved.attributes.update(base_decl.attributes)\n\n    # inherit base (if any)\n    if base_decl.base_qname:\n        base = get_resolved_complex_decl(idx, base_decl.base_qname)\n        if base is not None:\n            # base first, then derived overrides\n            merged = ComplexTypeDecl(name=resolved.name, base_qname=resolved.base_qname, derivation=resolved.derivation)\n            merged.elements.update(base.elements)\n            merged.elements.update(resolved.elements)\n            merged.attributes.update(base.attributes)\n            merged.attributes.update(resolved.attributes)\n            resolved = merged\n\n    idx._resolved_complex_cache[local] = resolved\n    return resolved\n\ndef get_child_element_decl(idx: SchemaIndex, parent_type_qname: Optional[str], child_name: str) -> Optional[PropDecl]:\n    parent = get_resolved_complex_decl(idx, parent_type_qname)\n    if not parent:\n        return None\n    # direct name match\n    if child_name in parent.elements:\n        pd = parent.elements[child_name]\n        # resolve ref if needed\n        if pd.ref_name:\n            ge = idx.global_elements.get(pd.ref_name)\n            if ge:\n                return PropDecl(name=child_name, kind="element", type_qname=ge.type_qname, ref_name=pd.ref_name,\n                                min_occurs=pd.min_occurs, max_occurs=pd.max_occurs)\n        return pd\n    return None\n\ndef get_attribute_decl(idx: SchemaIndex, parent_type_qname: Optional[str], attr_name: str) -> Optional[PropDecl]:\n    parent = get_resolved_complex_decl(idx, parent_type_qname)\n    if not parent:\n        return None\n    return parent.attributes.get(attr_name)\n\n\n# ----------------------------\n# Naming: property IRI local name\n# ----------------------------\n\ndef make_prop_local(domain_class: str, raw_name: str, *, is_attr: bool, rules: Dict[str, Any]) -> Tuple[str, str]:\n    naming = rules.get("naming", {}) or {}\n    lower_first_properties = bool(naming.get("lower_first_properties", True))\n    contextual = bool(naming.get("contextual_properties", False))\n\n    pname_raw = lower_first(raw_name) if lower_first_properties else raw_name\n    pname = pname_raw\n    if contextual:\n        if is_attr:\n            pname = f"{domain_class}/@{pname_raw}"\n        else:\n            pname = f"{domain_class}/{pname_raw}"\n    return pname, pname_raw\n\n\n# ----------------------------\n# Enum URI creation\n# ----------------------------\n\ndef normalize_enum_value(v: str, rules: Dict[str, Any]) -> str:\n    enum_cfg = rules.get("enum", {}) or {}\n    mode = str(enum_cfg.get("value_normalization", "lower_first") or "lower_first").lower()\n    if mode == "raw":\n        s = v\n    elif mode == "lower":\n        s = v.lower()\n    elif mode == "slug":\n        s = _slug(v)\n    elif mode == "quote":\n        s = urllib.parse.quote(v, safe="")\n    else:\n        # lower_first\n        s = lower_first(v)\n    # leading digit\n    if s and s[0].isdigit():\n        pref = str(enum_cfg.get("leading_digit_prefix", "v") or "v")\n        s = pref + s\n    return s\n\ndef enum_value_uri(type_name: str, raw_value: str, rules: Dict[str, Any], base_ns: str) -> URIRef:\n    enum_cfg = rules.get("enum", {}) or {}\n    # explicit maps first\n    by_type = enum_cfg.get("value_uri_map_by_type", {}) or {}\n    if isinstance(by_type, dict) and type_name in by_type and isinstance(by_type[type_name], dict):\n        if raw_value in by_type[type_name]:\n            return URIRef(str(by_type[type_name][raw_value]))\n    global_map = enum_cfg.get("value_uri_map", {}) or {}\n    if isinstance(global_map, dict) and raw_value in global_map:\n        return URIRef(str(global_map[raw_value]))\n\n    templ = str(enum_cfg.get("uri_template", "{base_ns}{type}#{value}") or "{base_ns}{type}#{value}")\n    val_norm = normalize_enum_value(raw_value, rules)\n    return URIRef(templ.format(base_ns=base_ns, type=type_name, value=val_norm))\n\n\n# ----------------------------\n# Unit URI creation\n# ----------------------------\n\ndef normalize_unit_token(u: str, rules: Dict[str, Any]) -> str:\n    meas = rules.get("measurement", {}) or {}\n    mode = str(meas.get("unit_normalization", "quote") or "quote").lower()\n    if mode == "raw":\n        return u\n    if mode == "slug":\n        return _slug(u)\n    # quote\n    return urllib.parse.quote(u, safe="")\n\ndef unit_uri(unit_value: str, unit_kind: str, rules: Dict[str, Any]) -> URIRef:\n    meas = rules.get("measurement", {}) or {}\n    m = meas.get("unit_uri_map", {}) or {}\n    if isinstance(m, dict) and unit_value in m:\n        return URIRef(str(m[unit_value]))\n\n    unit_base = str(meas.get("unit_base_ns", "") or "").strip()\n    if not unit_base:\n        unit_base = PLACEHOLDER_BASE_NS + "unit/"\n    if not unit_base.endswith("/"):\n        unit_base += "/"\n\n    templ = str(meas.get("unit_uri_template", "{unit_base}{kind}#{unit}") or "{unit_base}{kind}#{unit}")\n    u_norm = normalize_unit_token(unit_value, rules)\n    kind = unit_kind or "Unit"\n    return URIRef(templ.format(unit_base=unit_base, kind=kind, unit=u_norm))\n\n\n# ----------------------------\n# Quantity node creation\n# ----------------------------\n\n@dataclass(frozen=True)\nclass QuantityKey:\n    value_lex: str\n    datatype_uri: str\n    unit_uri: str\n    qclass_uri: str\n\ndef quantity_class_uri_for_property(prop_local: str, rules: Dict[str, Any]) -> Optional[URIRef]:\n    meas = rules.get("measurement", {}) or {}\n    by_prop = meas.get("quantity_class_by_property", {}) or {}\n    if isinstance(by_prop, dict) and prop_local in by_prop and by_prop[prop_local]:\n        return URIRef(str(by_prop[prop_local]))\n    default_uri = str(meas.get("value_class_uri", "") or "").strip()\n    if default_uri:\n        return URIRef(default_uri)\n    return None\n\n\n# ----------------------------\n# Instance URI management\n# ----------------------------\n\ndef instance_uri_for(class_local: str, id_value: str, rules: Dict[str, Any], inst_base: str, name_style: str) -> URIRef:\n    inst_cfg = rules.get("instance", {}) or {}\n    pattern = str(inst_cfg.get("uri_pattern", "{base}{class}/{id}") or "{base}{class}/{id}")\n    return URIRef(pattern.format(**{\n        "base": inst_base,\n        "class": encode_name(class_local, name_style),\n        "id": encode_name(id_value, name_style),\n    }))\n\ndef auto_id_for(class_local: str, counters: Dict[str, int], rules: Dict[str, Any]) -> str:\n    inst_cfg = rules.get("instance", {}) or {}\n    mode = str(inst_cfg.get("auto_id_prefix_mode", "class") or "class").lower()\n    if mode == "fixed":\n        prefix = str(inst_cfg.get("auto_id_prefix_fixed", "obj") or "obj")\n    else:\n        prefix = class_local\n    start = int(inst_cfg.get("auto_id_start", 0) or 0)\n    n = counters.get(class_local, start)\n    counters[class_local] = n + 1\n    return f"{prefix}:{n}"\n\ndef get_or_mint_node_for_id(id_value: str,\n                            class_local: str,\n                            id_map: Dict[str, URIRef],\n                            class_by_id: Dict[str, str],\n                            counters: Dict[str, int],\n                            rules: Dict[str, Any],\n                            inst_base: str,\n                            name_style: str) -> Tuple[URIRef, bool]:\n    """\n    Return (node_uri, is_new).\n    If id_value is empty, auto-generate an ID and mint URI.\n    """\n    if not id_value:\n        id_value = auto_id_for(class_local, counters, rules)\n\n    if id_value in id_map:\n        # keep the first class seen, but remember if different\n        return id_map[id_value], False\n\n    uri = instance_uri_for(class_local, id_value, rules, inst_base, name_style)\n    id_map[id_value] = uri\n    class_by_id.setdefault(id_value, class_local)\n    return uri, True\n\n\n# ----------------------------\n# Conversion contexts\n# ----------------------------\n\n@dataclass\nclass ElemCtx:\n    name: str\n    schema_type_qname: Optional[str]\n    class_local: Optional[str] = None\n    node: Optional[URIRef] = None\n    is_ref: bool = False\n    # For unit pairing inside this element (for child elements)\n    pending_values: Dict[str, Tuple[str, Optional[URIRef], Optional[str]]] = field(default_factory=dict)\n    pending_units: Dict[str, Tuple[str, str]] = field(default_factory=dict)  # base -> (unit_value, unit_kind)\n    # track unresolved referenced IDs from within this element\n    # (global tracking is done separately)\n\n\n# ----------------------------\n# Main conversion\n# ----------------------------\n\ndef convert(xsd_path: Path, xml_path: Path, rules: Dict[str, Any]) -> Tuple[Graph, Dict[str, Any], List[RuleIssue]]:\n    """\n    Returns (graph, stats, runtime_issues)\n    """\n    quiet = bool((rules.get("logging", {}) or {}).get("quiet", False))\n    name_style = str((rules.get("naming", {}) or {}).get("name_style", "raw") or "raw")\n    base_ns = str((rules.get("project", {}) or {}).get("base_ns", PLACEHOLDER_BASE_NS))\n    inst_base = str((rules.get("instance", {}) or {}).get("base_ns", PLACEHOLDER_INSTANCE_NS))\n\n    # load schema\n    follow_includes = bool((rules.get("input", {}) or {}).get("follow_includes", False))\n    xsd_files, unresolved = discover_xsd_set(xsd_path, follow_includes)\n    idx = build_schema_index(xsd_files)\n\n    if unresolved and not quiet:\n        print(f"WARN: unresolved schemaLocation(include/import) count={len(unresolved)} example={unresolved[:3]}")\n\n    # configs\n    ref_cfg = rules.get("ref", {}) or {}\n    ref_suffix = str(ref_cfg.get("element_suffix", "Ref") or "Ref")\n    ref_id_attr = str(ref_cfg.get("id_attribute", "ID") or "ID")\n    ref_strip_prop = bool(ref_cfg.get("strip_suffix_for_property", True))\n    ref_strip_class = bool(ref_cfg.get("strip_suffix_for_class", True))\n\n    enum_cfg = rules.get("enum", {}) or {}\n    enum_as_uri = bool(enum_cfg.get("as_uri", True))\n    enum_unknown_policy = str(enum_cfg.get("unknown_value_policy", "warn_uri") or "warn_uri").lower()\n\n    meas_cfg = rules.get("measurement", {}) or {}\n    numeric_default = str(meas_cfg.get("numeric_default", "object") or "object").lower()\n    unit_suffix = str(meas_cfg.get("unit_suffix", "Unit") or "Unit")\n    skip_unit_props = bool(meas_cfg.get("skip_unit_properties", True))\n    dedup_qty = bool(meas_cfg.get("deduplicate_quantity_nodes", True))\n\n    unitless_list = set(meas_cfg.get("unitless_literal_properties", []) or [])\n    unitless_patterns = []\n    for p in meas_cfg.get("unitless_literal_property_patterns", []) or []:\n        try:\n            unitless_patterns.append(re.compile(p))\n        except re.error:\n            pass\n\n    def is_unitless_literal(prop_final: str, prop_raw: str) -> bool:\n        if prop_final in unitless_list or prop_raw in unitless_list:\n            return True\n        for rx in unitless_patterns:\n            if rx.search(prop_final) or rx.search(prop_raw):\n                return True\n        return False\n\n    # graph\n    g = Graph()\n    VOC = Namespace(base_ns)\n    INST = Namespace(inst_base)\n    g.bind("", VOC)\n    g.bind("inst", INST)\n    g.bind("rdf", RDF)\n    g.bind("rdfs", RDFS)\n    g.bind("owl", OWL)\n    g.bind("xsd", XSD)\n    g.bind("dcterms", DCTERMS)\n    g.bind("qudt", QUDT)\n\n    # state\n    ctx_stack: List[ElemCtx] = []\n    id_map: Dict[str, URIRef] = {}\n    class_by_id: Dict[str, str] = {}\n    counters: Dict[str, int] = {}\n    referenced_ids: Set[str] = set()\n    defined_ids: Set[str] = set()\n    runtime_issues: List[RuleIssue] = []\n\n    qty_cache: Dict[QuantityKey, BNode] = {}\n\n    # identifier predicate\n    inst_cfg = rules.get("instance", {}) or {}\n    emit_identifier = bool(inst_cfg.get("emit_identifier_triple", True))\n    identifier_pred = URIRef(str(inst_cfg.get("identifier_predicate", str(DCTERMS.identifier)) or str(DCTERMS.identifier)))\n    id_attr_name = str(inst_cfg.get("id_attribute", "ID") or "ID")\n    allow_forward = bool(inst_cfg.get("allow_forward_refs", True))\n\n    # helper for property IRI\n    def prop_uri(domain_class: str, raw: str, is_attr: bool) -> URIRef:\n        p_local, _ = make_prop_local(domain_class, raw, is_attr=is_attr, rules=rules)\n        return VOC[encode_name(p_local, name_style)]\n\n    # helper: add literal with datatype (best-effort)\n    def add_literal(s: URIRef, p: URIRef, lex: str, dtype: Optional[URIRef]) -> None:\n        if dtype is None:\n            g.add((s, p, Literal(lex)))\n        else:\n            # Try cast for boolean\n            if dtype == XSD.boolean:\n                low = lex.strip().lower()\n                if low in ("true", "1"):\n                    g.add((s, p, Literal(True)))\n                elif low in ("false", "0"):\n                    g.add((s, p, Literal(False)))\n                else:\n                    g.add((s, p, Literal(lex, datatype=XSD.boolean)))\n            else:\n                g.add((s, p, Literal(lex, datatype=dtype)))\n\n    # helper: create quantity node and link\n    def add_quantity(subject: URIRef,\n                     p: URIRef,\n                     prop_local: str,\n                     value_lex: str,\n                     dtype: URIRef,\n                     unit_val: Optional[str],\n                     unit_kind: str) -> None:\n        qclass = quantity_class_uri_for_property(prop_local, rules)\n        unit_u = unit_uri(unit_val, unit_kind, rules) if unit_val else None\n\n        key = None\n        qnode = None\n        if dedup_qty:\n            key = QuantityKey(\n                value_lex=value_lex,\n                datatype_uri=str(dtype),\n                unit_uri=str(unit_u) if unit_u else "",\n                qclass_uri=str(qclass) if qclass else ""\n            )\n            qnode = qty_cache.get(key)\n\n        if qnode is None:\n            qnode = BNode()\n            # optionally type\n            if qclass is not None:\n                g.add((qnode, RDF.type, qclass))\n            # value\n            g.add((qnode, RDF.value, Literal(value_lex, datatype=dtype)))\n            # unit\n            if unit_u is not None:\n                g.add((qnode, QUDT_UNIT, unit_u))\n            if dedup_qty and key is not None:\n                qty_cache[key] = qnode\n\n        g.add((subject, p, qnode))\n\n    # helper: process a primitive property (literal/enum/quantity)\n    def process_value(subject: URIRef,\n                      domain_class: str,\n                      raw_name: str,\n                      is_attr: bool,\n                      value_lex: str,\n                      declared_type_qname: Optional[str],\n                      enum_type_name: Optional[str],\n                      enum_values: Optional[List[str]],\n                      unit_info: Optional[Tuple[str, str]]) -> None:\n        p_local, p_raw = make_prop_local(domain_class, raw_name, is_attr=is_attr, rules=rules)\n        p = VOC[encode_name(p_local, name_style)]\n\n        # enum?\n        if enum_values is not None and len(enum_values) > 0:\n            if enum_as_uri:\n                in_list = value_lex in enum_values\n                if not in_list:\n                    msg = f\'Enum value "{value_lex}" is not in XSD enumeration list (type={enum_type_name}, property={p_local}).\'\n                    if enum_unknown_policy == "strict":\n                        raise ValueError(msg)\n                    runtime_issues.append(RuleIssue(\n                        code="XR-ENUM-001",\n                        level="WARN",\n                        message=msg,\n                        details={"type": enum_type_name, "property": p_local, "value": value_lex}\n                    ))\n                    if enum_unknown_policy == "literal":\n                        add_literal(subject, p, value_lex, XSD.string)\n                        return\n                # mint URI\n                tname = enum_type_name or raw_name\n                g.add((subject, p, enum_value_uri(tname, value_lex, rules, base_ns)))\n                return\n            else:\n                add_literal(subject, p, value_lex, XSD.string)\n                return\n\n        # numeric?\n        is_num = is_numeric_type(idx, declared_type_qname)\n        if is_num and numeric_default == "object" and not is_unitless_literal(p_local, p_raw):\n            dtype = xsd_datatype_uri(idx, declared_type_qname)\n            unit_val = unit_info[0] if unit_info else None\n            unit_kind = unit_info[1] if unit_info else "Unit"\n            add_quantity(subject, p, p_local, value_lex, dtype, unit_val, unit_kind)\n            return\n\n        # boolean?\n        if is_boolean_type(idx, declared_type_qname):\n            add_literal(subject, p, value_lex, XSD.boolean)\n            return\n\n        # default: literal with best-effort datatype\n        dtype = xsd_datatype_uri(idx, declared_type_qname)\n        # if dtype is xsd:string or unknown, keep literal\n        add_literal(subject, p, value_lex, dtype if dtype != XSD.string else None)\n\n    # helper: determine enum list and type name from declared type\n    def enum_info_from_type(declared_type_qname: Optional[str]) -> Tuple[Optional[str], Optional[List[str]]]:\n        if not declared_type_qname:\n            return None, None\n        _, local = split_qname(declared_type_qname)\n        if local in idx.simple_types:\n            st = idx.simple_types[local]\n            if st.enumerations:\n                return local, st.enumerations\n        return None, None\n\n    # helper: flush pending values at element close\n    def flush_pending(ctx: ElemCtx):\n        if not ctx.node or not ctx.class_local:\n            return\n        # For any pending_values without unit, emit quantity nodes without unit (still object)\n        for base, (val_lex, dtype, declared_type) in list(ctx.pending_values.items()):\n            unit = ctx.pending_units.get(base)\n            unit_val = unit[0] if unit else None\n            unit_kind = unit[1] if unit else "Unit"\n            p = prop_uri(ctx.class_local, base, is_attr=False)\n            # Decide numeric or literal: pending_values are only used for numeric_object paths\n            add_quantity(ctx.node, p, make_prop_local(ctx.class_local, base, is_attr=False, rules=rules)[0], val_lex, dtype or XSD.decimal, unit_val, unit_kind)\n        ctx.pending_values.clear()\n        ctx.pending_units.clear()\n\n    # XML parse\n    for ev, elem in ET.iterparse(str(xml_path), events=("start", "end")):\n        if ev == "start":\n            ename = local_name(elem.tag)\n\n            parent_ctx = ctx_stack[-1] if ctx_stack else None\n\n            # schema type qname resolution for this element\n            declared_type = None\n            if parent_ctx is None:\n                ge = idx.global_elements.get(ename)\n                declared_type = ge.type_qname if ge else None\n            else:\n                pd = get_child_element_decl(idx, parent_ctx.schema_type_qname, ename)\n                declared_type = pd.type_qname if pd else None\n\n            # reference element?\n            is_ref = False\n            if ename.endswith(ref_suffix) and (ref_id_attr in elem.attrib):\n                is_ref = True\n\n            if is_ref:\n                # Create property link to referenced node\n                if parent_ctx is not None and parent_ctx.node is not None and parent_ctx.class_local is not None:\n                    raw_prop = ename[:-len(ref_suffix)] if ref_strip_prop else ename\n                    raw_cls = ename[:-len(ref_suffix)] if ref_strip_class else ename\n                    ref_id_val = elem.attrib.get(ref_id_attr, "")\n                    referenced_ids.add(ref_id_val)\n\n                    # ensure URI exists\n                    node_uri, _ = get_or_mint_node_for_id(\n                        ref_id_val, raw_cls,\n                        id_map, class_by_id, counters,\n                        rules, inst_base, name_style\n                    )\n                    p = prop_uri(parent_ctx.class_local, raw_prop, is_attr=False)\n                    g.add((parent_ctx.node, p, node_uri))\n                ctx_stack.append(ElemCtx(name=ename, schema_type_qname=declared_type, is_ref=True))\n                continue\n\n            # Determine if complex: if schema says complexType exists\n            is_complex = False\n            if declared_type:\n                _, tlocal = split_qname(declared_type)\n                if tlocal in idx.complex_types:\n                    is_complex = True\n\n            # fallback heuristic if schema unknown:\n            if declared_type is None:\n                # treat as complex if it has attributes other than xmlns\n                has_attrs = any(not local_name(k).startswith("xmlns") for k in elem.attrib.keys())\n                is_complex = has_attrs\n\n            if is_complex:\n                # create node and type\n                class_local = ename  # default class name strategy: element name\n                id_val = elem.attrib.get(id_attr_name, "")\n                node_uri, is_new = get_or_mint_node_for_id(\n                    id_val, class_local, id_map, class_by_id, counters,\n                    rules, inst_base, name_style\n                )\n                if id_val:\n                    defined_ids.add(id_val)\n\n                # rdf:type\n                g.add((node_uri, RDF.type, VOC[encode_name(class_local, name_style)]))\n\n                # identifier triple\n                if emit_identifier and id_val:\n                    g.add((node_uri, identifier_pred, Literal(id_val)))\n\n                # link from parent\n                if parent_ctx is not None and parent_ctx.node is not None and parent_ctx.class_local is not None:\n                    p = prop_uri(parent_ctx.class_local, ename, is_attr=False)\n                    g.add((parent_ctx.node, p, node_uri))\n\n                # push ctx\n                ctx = ElemCtx(name=ename, schema_type_qname=declared_type, class_local=class_local, node=node_uri, is_ref=False)\n\n                # process attributes immediately\n                # Pre-store unit attributes if skip_unit_props\n                for ak, av in list(elem.attrib.items()):\n                    a_local = local_name(ak)\n                    if a_local.startswith("xmlns"):\n                        continue\n                    if a_local == id_attr_name:\n                        continue\n\n                    # schema attribute decl\n                    a_decl = get_attribute_decl(idx, declared_type, a_local)\n                    a_type = a_decl.type_qname if a_decl else None\n                    # xsd default/fixed (if attribute absent in XML, not handled here)\n                    # Here we only see present attrs.\n\n                    # unit attribute?\n                    if skip_unit_props and a_local.endswith(unit_suffix):\n                        base = a_local[:-len(unit_suffix)]\n                        kind = infer_unit_kind_from_type(a_type)\n                        ctx.pending_units[base] = (av, kind)\n                        continue\n\n                    # numeric + object? we may wait for unit or handle now\n                    enum_tname, enum_vals = enum_info_from_type(a_type)\n\n                    # unit pairing info if available\n                    unit_info = None\n                    if numeric_default == "object" and is_numeric_type(idx, a_type):\n                        # try paired unit attribute\n                        paired_name = a_local + unit_suffix\n                        if paired_name in elem.attrib:\n                            uval = elem.attrib.get(paired_name)\n                            # Determine unit kind from that unit attribute\'s declared type\n                            u_decl = get_attribute_decl(idx, declared_type, paired_name)\n                            u_kind = infer_unit_kind_from_type(u_decl.type_qname if u_decl else None)\n                            unit_info = (uval, u_kind)\n                        else:\n                            # may be in ctx.pending_units if seen earlier\n                            if a_local in ctx.pending_units:\n                                unit_info = ctx.pending_units[a_local]\n\n                    # decide if numeric quantity should be delayed (to wait for unit)\n                    p_local_final, p_raw = make_prop_local(class_local, a_local, is_attr=True, rules=rules)\n                    if is_numeric_type(idx, a_type) and numeric_default == "object" and not is_unitless_literal(p_local_final, p_raw):\n                        # if we already have unit_info, create now\n                        if unit_info is not None:\n                            process_value(node_uri, class_local, a_local, True, av, a_type, enum_tname, enum_vals, unit_info)\n                        else:\n                            # delay; store value and datatype\n                            dtype = xsd_datatype_uri(idx, a_type)\n                            ctx.pending_values[a_local] = (av, dtype, a_type)\n                        continue\n\n                    # otherwise process now\n                    process_value(node_uri, class_local, a_local, True, av, a_type, enum_tname, enum_vals, unit_info)\n\n                ctx_stack.append(ctx)\n            else:\n                # simple element; we will process at end\n                ctx_stack.append(ElemCtx(name=ename, schema_type_qname=declared_type, class_local=None, node=None, is_ref=False))\n\n        else:  # end\n            ename = local_name(elem.tag)\n            if not ctx_stack:\n                elem.clear()\n                continue\n            ctx = ctx_stack.pop()\n            parent_ctx = ctx_stack[-1] if ctx_stack else None\n\n            if ctx.is_ref:\n                elem.clear()\n                continue\n\n            if ctx.node is None:\n                # simple element => attach to parent\n                text = (elem.text or "").strip()\n                if parent_ctx is not None and parent_ctx.node is not None and parent_ctx.class_local is not None and text != "":\n                    # unit element?\n                    if skip_unit_props and ename.endswith(unit_suffix):\n                        base = ename[:-len(unit_suffix)]\n                        # find declared type for this unit element if possible\n                        pd = get_child_element_decl(idx, parent_ctx.schema_type_qname, ename)\n                        u_kind = infer_unit_kind_from_type(pd.type_qname if pd else None)\n                        parent_ctx.pending_units[base] = (text, u_kind)\n                    else:\n                        # declared schema type for this element\n                        pd = get_child_element_decl(idx, parent_ctx.schema_type_qname, ename)\n                        etype = pd.type_qname if pd else None\n\n                        enum_tname, enum_vals = enum_info_from_type(etype)\n\n                        # numeric unit pairing: check if unit already present\n                        unit_info = parent_ctx.pending_units.get(ename)\n                        # if numeric and object and not unitless: maybe delay until unit appears\n                        p_local_final, p_raw = make_prop_local(parent_ctx.class_local, ename, is_attr=False, rules=rules)\n                        if is_numeric_type(idx, etype) and numeric_default == "object" and not is_unitless_literal(p_local_final, p_raw):\n                            if unit_info is not None:\n                                process_value(parent_ctx.node, parent_ctx.class_local, ename, False, text, etype, enum_tname, enum_vals, unit_info)\n                            else:\n                                dtype = xsd_datatype_uri(idx, etype)\n                                parent_ctx.pending_values[ename] = (text, dtype, etype)\n                        else:\n                            process_value(parent_ctx.node, parent_ctx.class_local, ename, False, text, etype, enum_tname, enum_vals, unit_info)\n\n                elem.clear()\n                continue\n\n            # complex element close: flush pending measurement values\n            flush_pending(ctx)\n            elem.clear()\n\n    # Post-run: unresolved refs warnings\n    unresolved_ids = sorted(list(referenced_ids - defined_ids))\n    if unresolved_ids and allow_forward:\n        runtime_issues.append(RuleIssue(\n            code="XR-REF-001",\n            level="WARN",\n            message="参照(Ref)されたIDのうち、XML内で定義が見つからないものがあります（前方参照の未解決 or 欠落）。",\n            details={"unresolved_ids_sample": unresolved_ids[:50], "unresolved_ids_count": len(unresolved_ids)}\n        ))\n    elif unresolved_ids and not allow_forward:\n        runtime_issues.append(RuleIssue(\n            code="XR-REF-002",\n            level="ERROR",\n            message="allow_forward_refs=false ですが、未解決の参照IDがあります。",\n            details={"unresolved_ids_sample": unresolved_ids[:50], "unresolved_ids_count": len(unresolved_ids)}\n        ))\n\n    stats = {\n        "xsd_files": len(xsd_files),\n        "simple_types": len(idx.simple_types),\n        "complex_types": len(idx.complex_types),\n        "global_elements": len(idx.global_elements),\n        "defined_ids": len(defined_ids),\n        "referenced_ids": len(referenced_ids),\n        "unresolved_ref_ids": len(unresolved_ids),\n        "triples": len(g),\n    }\n    return g, stats, runtime_issues\n\n\n# ----------------------------\n# CLI\n# ----------------------------\n\ndef main():\n    ap = argparse.ArgumentParser(description="XML-RDF Convertor v1.0 (instance): XML(instance) -> RDF(ABox) converter driven by XSD + rules (JSON/TSV)")\n    ap.add_argument("xsd", nargs="?", default="", help="XSD file or directory")\n    ap.add_argument("xml", nargs="?", default="", help="XML instance file")\n    ap.add_argument("-o", "--out", default="", help="Output TTL path (default: <xml>.ttl)")\n    ap.add_argument("--rules", default="", help="Rule file (.json or .tsv)")\n    ap.add_argument("--init-rules", default="", help="Write default rules (including defaults) to this path (.json/.tsv) and exit.")\n    ap.add_argument("--dump-effective-rules", default="", help="Write effective rules (defaults + overrides) to this path (.json/.tsv) and exit.")\n    ap.add_argument("--dry-run", action="store_true", help="Only print config + warnings; do not convert.")\n    args = ap.parse_args()\n\n    # init rules and exit\n    if args.init_rules:\n        out = Path(args.init_rules)\n        if out.suffix.lower() == ".json":\n            out.write_text(json.dumps(DEFAULT_RULES, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n        else:\n            write_rules_tsv(out, DEFAULT_RULES, include_header=True)\n        print(f"OK: wrote default rules to {out}")\n        return\n\n    overrides, rules_format = load_rules_file(args.rules) if args.rules else ({}, "none")\n    eff = compute_effective_rules(DEFAULT_RULES, overrides)\n    eff, issues = validate_rules(eff, rules_format=rules_format)\n\n    quiet = bool((eff.get("logging", {}) or {}).get("quiet", False))\n    print_effective_mode = str((eff.get("logging", {}) or {}).get("print_effective_config", "summary") or "summary").lower()\n    if quiet:\n        print_effective_mode = "none"\n    if print_effective_mode not in ("summary", "full", "none"):\n        print_effective_mode = "summary"\n\n    if not quiet:\n        print_effective_config(eff, print_effective_mode)\n\n    validation_mode = str((eff.get("validation", {}) or {}).get("mode", "warn") or "warn").lower()\n    print_patches = bool((eff.get("validation", {}) or {}).get("print_patches", True))\n    todo_patch_path = str((eff.get("validation", {}) or {}).get("todo_patch_path", "") or "")\n\n    if validation_mode in ("warn", "strict") and not quiet:\n        print_issues(issues, rules_format="tsv" if rules_format == "tsv" else "json", print_patches=print_patches)\n\n    if validation_mode == "strict":\n        if any(i.level == "ERROR" for i in issues):\n            raise SystemExit("Aborting due to missing required rules (strict mode).")\n\n    # dump effective and exit\n    if args.dump_effective_rules:\n        out = Path(args.dump_effective_rules)\n        if out.suffix.lower() == ".json":\n            out.write_text(json.dumps(eff, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n        else:\n            write_rules_tsv(out, eff, include_header=True)\n        print(f"OK: wrote effective rules to {out}")\n        return\n\n    if args.dry_run:\n        print("Dry-run: no conversion executed.")\n        return\n\n    if not args.xsd or not args.xml:\n        raise SystemExit("Usage: xml_rdf_convertor_instance.py <schema.xsd> <instance.xml> --rules rules.tsv -o out.ttl")\n\n    xsd_path = Path(args.xsd)\n    xml_path = Path(args.xml)\n    out_path = Path(args.out) if args.out else xml_path.with_suffix(".ttl")\n\n    g, stats, runtime_issues = convert(xsd_path, xml_path, eff)\n\n    # runtime issues\n    if validation_mode in ("warn", "strict") and runtime_issues and not quiet:\n        print_issues(runtime_issues, rules_format="tsv" if rules_format == "tsv" else "json", print_patches=False)\n\n    if validation_mode == "strict":\n        if any(i.level == "ERROR" for i in runtime_issues):\n            raise SystemExit("Aborting due to runtime rule violations (strict mode).")\n\n    # TODO patch output (from validation issues only, for now)\n    if todo_patch_path:\n        patch: Dict[str, Any] = {}\n        for iss in issues:\n            if iss.suggested_patch:\n                deep_update(patch, iss.suggested_patch)\n        if patch:\n            p = Path(todo_patch_path)\n            if p.suffix.lower() == ".json":\n                p.write_text(json.dumps(patch, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")\n            else:\n                write_rules_tsv(p, patch, include_header=True)\n            if not quiet:\n                print(f"OK: wrote TODO patch to {p}")\n\n    ttl = g.serialize(format="turtle")\n    out_path.write_bytes(ttl if isinstance(ttl, (bytes, bytearray)) else ttl.encode("utf-8"))\n\n    if not quiet:\n        print(f"OK: wrote instance RDF to {out_path}")\n        print("Stats:", json.dumps(stats, ensure_ascii=False, indent=2))\n\n'

_namespace_cache = {}

def _load_namespace(kind: str):
    if kind in _namespace_cache:
        return _namespace_cache[kind]
    source = _SCHEMA_SOURCE if kind == "schema" else _INSTANCE_SOURCE
    filename = "xml_rdf_convertor_schema.py" if kind == "schema" else "xml_rdf_convertor_instance.py"
    module_name = f"xml_rdf_convertor_embedded_{kind}"
    module = types.ModuleType(module_name)
    module.__file__ = filename
    module.__package__ = None
    # dataclasses and some introspection expect the module to be present in sys.modules
    sys.modules[module_name] = module
    ns = module.__dict__
    exec(compile(source, filename, "exec"), ns, ns)
    _namespace_cache[kind] = ns
    return ns

def _run_embedded(kind: str, argv: list[str]) -> int:
    ns = _load_namespace(kind)
    main = ns.get("main")
    if main is None:
        print(f"ERROR: embedded {kind} converter has no main()", file=sys.stderr)
        return 2
    old_argv = sys.argv[:]
    sys.argv = [f"xml_rdf_convertor.py {kind}"] + list(argv)
    try:
        result = main()
        return int(result) if isinstance(result, int) else 0
    except SystemExit as e:
        code = e.code
        if code is None:
            return 0
        if isinstance(code, int):
            return code
        print(code, file=sys.stderr)
        return 1
    finally:
        sys.argv = old_argv

def main() -> int:
    argv = sys.argv[1:]

    # Global flags
    if not argv or argv[0] in ("-h", "--help"):
        print(f"{PROGRAM_NAME} {PROGRAM_VERSION} (single-file distribution)\n")
        print("Usage:")
        print("  xml_rdf_convertor.py schema   [schema-converter-options]")
        print("  xml_rdf_convertor.py instance [instance-converter-options]")
        print("  xml_rdf_convertor.py --version")
        return 0

    if argv[0] == "--version":
        print(f"{PROGRAM_NAME} {PROGRAM_VERSION}")
        return 0

    cmd = argv[0]
    rest = argv[1:]

    if cmd == "schema":
        return _run_embedded("schema", rest)
    if cmd == "instance":
        return _run_embedded("instance", rest)

    print(f"ERROR: unknown subcommand: {cmd}", file=sys.stderr)
    print("Use --help to see available subcommands.", file=sys.stderr)
    return 2

if __name__ == "__main__":
    raise SystemExit(main())
